34:     
35:     let mut results = Vec::new();
36:     for item in res.items.items {
37:         if let rustypipe::model::YouTubeItem::Video(v) = item {
38:             let thumbs = v.thumbnail.into_iter().map(|t| Thumbnail { url: t.url }).collect();
39:             results.push(SearchResult {
40:                 id: v.id.clone(),
41:                 title: v.name,
42:                 url: format!("https://youtube.com/watch?v={}", v.id),
43:                 thumbnails: thumbs,
44:             });
