143:         let _ = writeln!(f, "TITLE \"{}\"", set_title);
144:         let _ = writeln!(f, "FILE \"Tracklist\" MP3");
145:         for (i, file) in track_files.iter().enumerate() {
146:             let _ = writeln!(f, "  TRACK {:02} AUDIO", i + 1);
147:             let _ = writeln!(f, "    TITLE \"{}\"", file);
148:             let _ = writeln!(f, "    INDEX 01 00:00:00");
149:         }
150:     }
151: 
