338: fn write_log(message: String) -> Result<(), String> {
339:     use std::fs::{OpenOptions, metadata, create_dir_all};
340:     use std::io::Write;
341:     use std::path::PathBuf;
342:     
343:     // Default to unified log file
344:     let docs_dir = dirs::document_dir().unwrap_or_else(|| PathBuf::from("/tmp"));
345:     let log_dir_path = docs_dir.join("OnyxYoutubeDownloader").join("Logs");
346:     
347:     if let Err(e) = create_dir_all(&log_dir_path) {
348:         return Err(format!("Failed to create log dir: {}", e));
349:     }
350:     
351:     let path = log_dir_path.join("onyx.log");
352:     
353:     // Check file size and truncate if larger than 1MB
354:     if let Ok(meta) = metadata(&path) {
355:         let size_mb = meta.len() / (1024 * 1024);
356:         if size_mb >= 1 {
357:             let _ = std::fs::remove_file(&path);
358:         }
359:     }
360:     
361:     let mut file = OpenOptions::new()
362:         .create(true)
363:         .append(true)
364:         .open(&path)
365:         .map_err(|e| e.to_string())?;
366:         
367:     let now = chrono::Local::now();
368:     writeln!(file, "{} - [FRONTEND] - {}", now.format("%Y-%m-%d %H:%M:%S,%3f"), message)
369:         .map_err(|e| e.to_string())?;
370:         
371:     Ok(())
372: }
