376:         return Err(format!("Failed to create log dir: {}", e));
377:     }
378:     
379:     let path = log_dir_path.join("onyx.log");
380:     
381:     // Check file size and truncate if larger than 1MB
382:     if let Ok(meta) = metadata(&path) {
383:         let size_mb = meta.len() / (1024 * 1024);
384:         if size_mb >= 1 {
385:             let _ = std::fs::remove_file(&path);
386:         }
387:     }
388:     
389:     let mut file = OpenOptions::new()
390:         .create(true)
391:         .append(true)
392:         .open(&path)
393:         .map_err(|e| e.to_string())?;
394:         
395:     let now = chrono::Local::now();
396:     writeln!(file, "{} - [FRONTEND] - {}", now.format("%Y-%m-%d %H:%M:%S,%3f"), message)
397:         .map_err(|e| e.to_string())?;
398:         
399:     Ok(())
400: }
