  const relayTopic = 'onyx_req_' + cleanRoom;
  try {
    await fetch('https://ntfy.sh/' + relayTopic, {
      method: 'POST',
      headers: {
        'Title': 'Song Request: ' + payload.title.slice(0, 50)
      },
      body: JSON.stringify(payload)
    });
  } catch(relayErr) {
    console.warn('Realtime cloud relay notice:', relayErr);
  }

  // 2. Also push to Firebase Realtime Database if configured
  if (roomRef) {
    try {
      await roomRef.child('requests').push(payload);
    } catch(e) {}
  }

  // 3. LocalStorage for same-browser testing
  const key = 'onyx_requests_' + roomId;
  const current = JSON.parse(localStorage.getItem(key) || '[]');
  current.push({ ...payload, id: 'req_' + Date.now() });
  localStorage.setItem(key, JSON.stringify(current));
  window.dispatchEvent(new Event('storage'));

