const paho = await import("./node_modules/paho-mqtt/paho-mqtt.js");
const Paho = paho.default;
const testTopic = "onyx/test_retain_" + Math.random().toString(36).substring(2, 7);

const pubClient = new Paho.Client("broker.hivemq.com", 8884, "/mqtt", "pub_" + Math.random().toString(36).substring(2, 7));

pubClient.connect({
  useSSL: true,
  timeout: 4,
  onSuccess: () => {
    console.log("Publisher connected");
    const msg = new Paho.Message(JSON.stringify({ active: false, test: 123 }));
    msg.destinationName = testTopic;
    msg.retained = true;
    msg.qos = 0;
    pubClient.send(msg);
    console.log("Message published with retained=true");
    setTimeout(() => {
      pubClient.disconnect();
      // Now test subscriber connecting after message was sent!
      const subClient = new Paho.Client("broker.hivemq.com", 8884, "/mqtt", "sub_" + Math.random().toString(36).substring(2, 7));
      subClient.onMessageArrived = (m) => {
        console.log("RETAINED MESSAGE RECEIVED BY NEW CLIENT:", m.payloadString, "retained:", m.retained);
        subClient.disconnect();
        process.exit(0);
      };
      subClient.connect({
        useSSL: true,
        timeout: 4,
        onSuccess: () => {
          console.log("Subscriber connected, subscribing to:", testTopic);
          subClient.subscribe(testTopic, { qos: 0 });
        }
      });
    }, 1000);
  },
  onFailure: (err) => {
    console.error("Connect fail:", err);
    process.exit(1);
  }
});
'

