// Global Event Room State
let isRoomActive = true;
let mqttStatusClient = null;

function initMqttStatusListener() {
  const cleanRoom = (roomId || 'SHAZZ-SONIC').toUpperCase().trim().replace(/[^A-Z0-9_-]/g, '') || 'SHAZZ-SONIC';
  const statusTopic = `onyx/status/${cleanRoom}`;
  const PahoLib = window.Paho;
  const Client = (PahoLib && PahoLib.MQTT && PahoLib.MQTT.Client) || (PahoLib && PahoLib.Client);
  if (!Client) return;

  const handleStatusMessage = (msg) => {
    try {
      const statusInfo = JSON.parse(msg.payloadString);
      console.log('[Guest MQTT] Received room status update:', statusInfo);
      const loadScreen = document.getElementById('loading-screen');
      if (loadScreen) loadScreen.style.display = 'none';

      if (statusInfo.active === false) {
        isRoomActive = false;
        showClosedState({ reason: 'inactive' });
        closeModal();
      } else if (statusInfo.active === true) {
        isRoomActive = true;
        showActiveState(statusInfo);
      }
    } catch(e) {
      console.warn('[Guest MQTT] Error parsing status payload:', e);
    }
  };

  // Try HiveMQ first
  try {
    const clientId = 'guest_status_' + Math.random().toString(36).substring(2, 9);
    mqttStatusClient = new Client('broker.hivemq.com', 8884, '/mqtt', clientId);
    mqttStatusClient.onMessageArrived = handleStatusMessage;
    mqttStatusClient.onConnectionLost = () => {
      setTimeout(initMqttStatusListener, 3500);
    };
    mqttStatusClient.connect({
      useSSL: true,
      timeout: 4,
      cleanSession: true,
      onSuccess: () => {
        console.log('[Guest MQTT] Subscribed to status on HiveMQ:', statusTopic);
        mqttStatusClient.subscribe(statusTopic, { qos: 0 });
      },
      onFailure: () => {
        tryEmqxFallback();
      }
    });
  } catch(e) {
    tryEmqxFallback();
  }

  function tryEmqxFallback() {
    try {
      const fbId = 'guest_status_fb_' + Math.random().toString(36).substring(2, 9);
      const emqx = new Client('broker.emqx.io', 8084, '/mqtt', fbId);
      emqx.onMessageArrived = handleStatusMessage;
      emqx.connect({
        useSSL: true,
        timeout: 4,
        cleanSession: true,
        onSuccess: () => {
          console.log('[Guest MQTT] Subscribed to status on EMQX fallback:', statusTopic);
          emqx.subscribe(statusTopic, { qos: 0 });
        }
      });
    } catch(e) {}
  }
}

// Monitor Event Status & Location
async function checkStatus() {
  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'flex';

  // 1. Explicitly closed in URL query param:
  if (urlParams.get('closed') === 'true') {
    isRoomActive = false;
    if (loadScreen) loadScreen.style.display = 'none';
    showClosedState({ reason: 'inactive' });
    return;
  }

  // 2. Verify Geofence first if configured
  if (hasGeofence) {
    const geoCheck = await verifyGuestLocation();
    if (!geoCheck.allowed) {
      if (loadScreen) loadScreen.style.display = 'none';
      showClosedState(geoCheck);
      return;
    }
  }

  // 3. Connect real-time status listener via MQTT retained channel
  initMqttStatusListener();

  // 4. Also check Firebase if configured
  if (roomRef) {
    roomRef.on('value', (snapshot) => {
      const data = snapshot.val();
      if (loadScreen) loadScreen.style.display = 'none';
      if (data && data.isActive) {
        isRoomActive = true;
        showActiveState(data);
      } else {
        isRoomActive = false;
        showClosedState({ reason: 'inactive' });
        closeModal();
      }
    });
  }

  // Fallback timeout in case MQTT status hasn't arrived within 1.2s
  setTimeout(() => {
    if (loadScreen && loadScreen.style.display !== 'none') {
      loadScreen.style.display = 'none';
      if (isRoomActive) {
        showActiveState({ djName: 'DJ Shazz & DJ Sonic' });
      }
    }
  }, 1200);
}

function showClosedState(info) {
  isRoomActive = false;
  closeModal();
  const results = document.getElementById('search-results');
  if (results) results.innerHTML = '';
  const input = document.getElementById('search-input');
  if (input) input.value = '';

  document.getElementById('state-closed').style.display = 'flex';
  document.getElementById('state-active').style.display = 'none';

  const mainMsg = document.getElementById('closed-main-msg');
  const subMsg = document.getElementById('closed-sub-msg');
  const retryBtn = document.getElementById('retry-location-btn');

  if (info && info.reason === 'outside') {
    const distTxt = info.distance >= 1000 
      ? (info.distance / 1000).toFixed(1) + ' ק"מ' 
      : info.distance + ' מטר';
    if (mainMsg) mainMsg.innerHTML = 'הגישה מותרת רק מתוך רחבת המסיבה 📍';
    if (subMsg) subMsg.innerHTML = `עמדת בקשת השירים פתוחה רק למי שנמצא ברדיוס של <b>${info.allowedRadius} מטר</b> מעמדת הדיג'יי.<br/>מרחקך כרגע: <b>כ-${distTxt}</b>.<br/>התקרבו לעמדה ונסו שוב!`;
    if (retryBtn) {
      retryBtn.style.display = 'block';
      retryBtn.innerText = 'בדוק מיקום שוב 🔄';
    }
  } else if (info && info.reason === 'denied') {
    if (mainMsg) mainMsg.innerHTML = 'נדרש אישור מיקום לבקשת שירים 📍';
    if (subMsg) subMsg.innerHTML = 'כדי לוודא שאתה נמצא במסיבה ולמנוע בקשות מבחוץ, יש לאשר גישה למיקום הדפדפן בסמארטפון.';
    if (retryBtn) {
      retryBtn.style.display = 'block';
      retryBtn.innerText = 'אשר מיקום ונסה שוב 🎯';
    }
  } else {
    if (mainMsg) mainMsg.innerHTML = 'המוזיקה נחה, אבל הקצב לא מפסיק... 💿';
    if (subMsg) subMsg.innerHTML = 'תודה ענקית על ערב מטורף ומלא אנרגיה! עמדת בקשות האורחים (Guest Requests) סגורה. נתראה בסט הבא!';
    if (retryBtn) retryBtn.style.display = 'none';
  }
}

function showActiveState(data) {
  isRoomActive = true;
  document.getElementById('state-closed').style.display = 'none';
  document.getElementById('state-active').style.display = 'flex';

  if (hasGeofence) {
    const badge = document.getElementById('geofence-badge');
    const distSpan = document.getElementById('geofence-dist-txt');
    if (badge && distSpan) {
      badge.style.display = 'inline-flex';
      distSpan.innerText = `(${guestDistance} מטר מהעמדה)`;
    }
  }

  const names = (data && (data.djNames || data.djName)) || 'DJ Shazz & DJ Sonic';
  const activeTitle = document.getElementById('active-dj-title');
  const closedTitle = document.getElementById('closed-dj-title');
  if (activeTitle) activeTitle.innerText = names;
  if (closedTitle) closedTitle.innerText = names;
}

