293: #[tauri::command]
294: fn get_system_memory() -> Result<SystemMemoryInfo, String> {
295:     // 1. Total RAM via sysctl hw.memsize
296:     let mut total_gb = 16.0;
297:     if let Ok(out) = Command::new("sysctl").args(&["-n", "hw.memsize"]).output() {
298:         if let Ok(s) = String::from_utf8(out.stdout) {
299:             if let Ok(bytes) = s.trim().parse::<f64>() {
300:                 total_gb = bytes / (1024.0 * 1024.0 * 1024.0);
301:             }
302:         }
303:     }
304: 
305:     // 2. Used / Free RAM approximation via vm_stat
306:     let mut free_pages: f64 = 0.0;
307:     let mut page_size: f64 = 4096.0;
308: 
309:     if let Ok(out) = Command::new("vm_stat").output() {
310:         if let Ok(s) = String::from_utf8(out.stdout) {
311:             for line in s.lines() {
312:                 if line.starts_with("page size of") {
313:                     if let Some(sz) = line.split_whitespace().nth(3) {
314:                         if let Ok(p) = sz.trim_end_matches('.').parse::<f64>() {
315:                             page_size = p;
316:                         }
317:                     }
318:                 } else if line.starts_with("Pages free:") {
319:                     if let Some(cnt) = line.split_whitespace().nth(2) {
320:                         if let Ok(p) = cnt.trim_end_matches('.').parse::<f64>() {
321:                             free_pages += p;
322:                         }
323:                     }
324:                 } else if line.starts_with("Pages speculative:") {
325:                     if let Some(cnt) = line.split_whitespace().nth(2) {
326:                         if let Ok(p) = cnt.trim_end_matches('.').parse::<f64>() {
327:                             free_pages += p;
328:                         }
329:                     }
330:                 }
331:             }
332:         }
333:     }
334: 
335:     let free_gb = (free_pages * page_size) / (1024.0 * 1024.0 * 1024.0);
336:     let used_gb = (total_gb - free_gb).max(0.0);
337: 
338:     Ok(SystemMemoryInfo {
339:         total_gb: (total_gb * 10.0).round() / 10.0,
340:         used_gb: (used_gb * 10.0).round() / 10.0,
341:         free_gb: (free_gb * 10.0).round() / 10.0,
342:     })
343: }
