const WebSocket = global.WebSocket;

// Connect subscriber
const wsSub = new WebSocket("wss://broker.hivemq.com:8884/mqtt", ["mqtt"]);
wsSub.onopen = () => {
  console.log("Sub connected");
  // Send MQTT CONNECT
  // Protocol: MQTT 3.1.1
  const connectPacket = Buffer.from([
    0x10, 0x12, // Connect packet, len 18
    0x00, 0x04, 0x4d, 0x51, 0x54, 0x54, // "MQTT"
    0x04, // level 4
    0x02, // clean session
    0x00, 0x3c, // keepalive 60
    0x00, 0x06, 0x73, 0x75, 0x62, 0x31, 0x32, 0x33 // client id "sub123"
  ]);
  wsSub.send(connectPacket);
};

wsSub.onmessage = (event) => {
  const buf = Buffer.from(event.data);
  console.log("Sub received packet type:", buf[0] >> 4);
  if ((buf[0] >> 4) === 2) {
    // Connack -> Subscribe
    console.log("Connack received, subscribing to onyx/status/SHAZZ-6217");
    const topic = "onyx/status/SHAZZ-6217";
    const subPacket = Buffer.concat([
      Buffer.from([0x82, topic.length + 5, 0x00, 0x01, 0x00, topic.length]),
      Buffer.from(topic),
      Buffer.from([0x00])
    ]);
    subPacket[1] = subPacket.length - 2;
    wsSub.send(subPacket);
  } else if ((buf[0] >> 4) === 3) {
    // Publish packet!
    console.log("PUBLISH RECEIVED!", buf.toString());
  }
};

setTimeout(() => {
  console.log("End test");
  process.exit(0);
}, 4000);
'

