// Extract Room & Geofence params from URL or persistent localStorage
const urlParams = new URLSearchParams(window.location.search);
let rawRoom = (urlParams.get('room') || '').trim();
if (!rawRoom) {
  rawRoom = localStorage.getItem('onyx_last_guest_room') || 'SHAZZ-SONIC';
} else {
  localStorage.setItem('onyx_last_guest_room', rawRoom);
}
const roomId = rawRoom.toUpperCase();
const cleanRoom = roomId.replace(/[^A-Z0-9_-]/g, '') || 'SHAZZ-SONIC';
const targetLat = parseFloat(urlParams.get('lat'));
const targetLon = parseFloat(urlParams.get('lon'));
const allowedRadius = parseFloat(urlParams.get('rad') || '30');
const hasGeofence = !isNaN(targetLat) && !isNaN(targetLon);

let guestDistance = 0;
let selectedTrack = null;
let roomRef = null;

// Haversine distance formula in meters
function calculateDistanceMeters(lat1, lon1, lat2, lon2) {
  const R = 6371e3; // Earth radius in meters
  const phi1 = lat1 * Math.PI / 180;
  const phi2 = lat2 * Math.PI / 180;
  const deltaPhi = (lat2 - lat1) * Math.PI / 180;
  const deltaLambda = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
            Math.cos(phi1) * Math.cos(phi2) *
            Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

// Verify Guest Device Location against Event Geofence
async function verifyGuestLocation() {
  if (!hasGeofence) return { allowed: true, distance: 0 };

  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve({ allowed: false, reason: 'unsupported' });
      return;
    }

    const loadText = document.getElementById('loading-text');
    if (loadText) loadText.innerText = 'מאמת נוכחות ברחבת המסיבה... 📍';

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const guestLat = pos.coords.latitude;
        const guestLon = pos.coords.longitude;
        const dist = calculateDistanceMeters(targetLat, targetLon, guestLat, guestLon);
        guestDistance = dist;

        if (dist <= allowedRadius) {
          resolve({ allowed: true, distance: dist });
        } else {
          resolve({ allowed: false, reason: 'outside', distance: dist, allowedRadius: allowedRadius });
        }
      },
      (err) => {
        console.warn('Geolocation permission error:', err);
        resolve({ allowed: false, reason: 'denied', error: err.message });
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 5000 }
    );
  });
}

// Optional Firebase Config (supports localStorage injection from DJ app or default free relay)
const savedConfig = localStorage.getItem('onyx_firebase_config');
let firebaseConfig = null;
try {
  if (savedConfig) firebaseConfig = JSON.parse(savedConfig);
} catch(e) {}

// Initialize Firebase if configured
let db = null;
if (firebaseConfig && firebaseConfig.apiKey) {
  try {
    if (!firebase.apps.length) firebase.initializeApp(firebaseConfig);
    db = firebase.database();
    roomRef = db.ref('events/' + roomId);
  } catch(e) {
    console.warn('Firebase init error', e);
  }
}

// Global Event Room State
let isRoomActive = true;
let mqttStatusClient = null;
let sseClient = null;

// ========================================================
// UNIFIED STATUS APPLIER (INSTANT PROACTIVE TRANSITION)
// ========================================================
function applyRoomStatus(statusInfo) {
  if (!statusInfo || typeof statusInfo.active !== 'boolean') return;

  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'none';

  if (statusInfo.active === false) {
    if (isRoomActive !== false) {
      console.log('[Room Status Event] Station closed by DJ -> Locking screen proactively');
      isRoomActive = false;
      showClosedState({ reason: 'inactive', djName: statusInfo.djNames });
    }
  } else if (statusInfo.active === true) {
    if (isRoomActive !== true) {
      console.log('[Room Status Event] Station opened by DJ -> Showing request screen');
      isRoomActive = true;
      showActiveState(statusInfo);
    }
  }
}

// 1. REAL-TIME SERVER-SENT EVENTS (SSE) via NTFY (PORT 443 HTTPS - ZERO BLOCKING)
function initSseStatusListener() {
  try {
    const sseUrl = `https://ntfy.sh/onyx_status_${cleanRoom.toLowerCase()}/sse`;
    sseClient = new EventSource(sseUrl);
    sseClient.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.event === 'message') {
          const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
          applyRoomStatus(payload);
        }
      } catch(e) {}
    };
    sseClient.onerror = () => {
      pollStatusHttp();
    };

    if (cleanRoom !== 'SHAZZ-SONIC') {
      const fallbackSource = new EventSource('https://ntfy.sh/onyx_status_shazz-sonic/sse');
      fallbackSource.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.event === 'message') {
            const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
            applyRoomStatus(payload);
          }
        } catch(e) {}
      };
    }
  } catch (err) {
    console.warn('[SSE] EventSource init error:', err);
  }
}

// 2. ACTIVE FAST HTTP POLLING (EVERY 2.5s OVER STANDARD HTTPS 443)
async function pollStatusHttp() {
  const tryFetch = async (target) => {
    try {
      const res = await fetch(`https://ntfy.sh/onyx_status_${target.toLowerCase()}/json?poll=1`, {
        cache: 'no-store',
        headers: { 'Accept': 'application/json' }
      });
      if (res.ok) {
        const text = await res.text();
        const lines = text.trim().split('\n');
        for (let i = lines.length - 1; i >= 0; i--) {
          try {
            const item = JSON.parse(lines[i]);
            if (item.event === 'message') {
              const payload = typeof item.message === 'string' ? JSON.parse(item.message) : item.message;
              if (payload && typeof payload.active === 'boolean') {
                applyRoomStatus(payload);
                return true;
              }
            }
          } catch(e) {}
        }
      }
    } catch(e) {}
    return false;
  };

  const found = await tryFetch(cleanRoom);
  if (!found && cleanRoom !== 'SHAZZ-SONIC') {
    await tryFetch('shazz-sonic');
  }
}

// 3. MQTT WEBSOCKET BROKER LISTENER (HiveMQ + EMQX)
function initMqttStatusListener() {
  const statusTopic = `onyx/status/${cleanRoom}`;
  const PahoLib = window.Paho;
  const Client = (PahoLib && PahoLib.MQTT && PahoLib.MQTT.Client) || (PahoLib && PahoLib.Client);
  if (!Client) return;

  const handleMsg = (msg) => {
    try {
      const statusInfo = JSON.parse(msg.payloadString);
      console.log('[Guest MQTT] Received room status update:', statusInfo);
      applyRoomStatus(statusInfo);
    } catch(e) {
      console.warn('[Guest MQTT] Error parsing status payload:', e);
    }
  };

  try {
    const clientId = 'guest_st_' + Math.random().toString(36).substring(2, 9);
    mqttStatusClient = new Client('broker.hivemq.com', 8884, '/mqtt', clientId);
    mqttStatusClient.onMessageArrived = handleMsg;
    mqttStatusClient.onConnectionLost = () => setTimeout(initMqttStatusListener, 4000);
    mqttStatusClient.connect({
      useSSL: true,
      timeout: 4,
      cleanSession: true,
      onSuccess: () => {
        mqttStatusClient.subscribe(statusTopic, { qos: 0 });
        if (cleanRoom !== 'SHAZZ-SONIC') mqttStatusClient.subscribe('onyx/status/SHAZZ-SONIC', { qos: 0 });
      },
      onFailure: tryEmqxFallback
    });
  } catch(e) {
    tryEmqxFallback();
  }

  function tryEmqxFallback() {
    try {
      const fbId = 'guest_st_fb_' + Math.random().toString(36).substring(2, 9);
      const emqx = new Client('broker.emqx.io', 8084, '/mqtt', fbId);
      emqx.onMessageArrived = handleMsg;
      emqx.connect({
        useSSL: true,
        timeout: 4,
        cleanSession: true,
        onSuccess: () => {
          emqx.subscribe(statusTopic, { qos: 0 });
          if (cleanRoom !== 'SHAZZ-SONIC') emqx.subscribe('onyx/status/SHAZZ-SONIC', { qos: 0 });
        }
      });
    } catch(e) {}
  }
}

// Monitor Event Status & Location
async function checkStatus() {
  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'flex';

  // 1. Explicitly closed in URL query param:
  if (urlParams.get('closed') === 'true') {
    isRoomActive = false;
    if (loadScreen) loadScreen.style.display = 'none';
    showClosedState({ reason: 'inactive' });
    return;
  }

  // 2. Verify Geofence first if configured
  if (hasGeofence) {
