// Extract Room & Geofence params from URL
const urlParams = new URLSearchParams(window.location.search);
const rawRoom = (urlParams.get('room') || 'SHAZZ-SONIC').trim();
const roomId = (rawRoom || 'SHAZZ-SONIC').toUpperCase();
const targetLat = parseFloat(urlParams.get('lat'));
const targetLon = parseFloat(urlParams.get('lon'));
const allowedRadius = parseFloat(urlParams.get('rad') || '30');
const hasGeofence = !isNaN(targetLat) && !isNaN(targetLon);

let guestDistance = 0;
let selectedTrack = null;
let roomRef = null;

// Haversine distance formula in meters
function calculateDistanceMeters(lat1, lon1, lat2, lon2) {
  const R = 6371e3; // Earth radius in meters
  const phi1 = lat1 * Math.PI / 180;
  const phi2 = lat2 * Math.PI / 180;
  const deltaPhi = (lat2 - lat1) * Math.PI / 180;
  const deltaLambda = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
            Math.cos(phi1) * Math.cos(phi2) *
            Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

// Verify Guest Device Location against Event Geofence
async function verifyGuestLocation() {
  if (!hasGeofence) return { allowed: true, distance: 0 };

  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve({ allowed: false, reason: 'unsupported' });
      return;
    }

    const loadText = document.getElementById('loading-text');
    if (loadText) loadText.innerText = 'מאמת נוכחות ברחבת המסיבה... 📍';

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const guestLat = pos.coords.latitude;
        const guestLon = pos.coords.longitude;
        const dist = calculateDistanceMeters(targetLat, targetLon, guestLat, guestLon);
        guestDistance = dist;

        if (dist <= allowedRadius) {
          resolve({ allowed: true, distance: dist });
        } else {
          resolve({ allowed: false, reason: 'outside', distance: dist, allowedRadius: allowedRadius });
        }
      },
      (err) => {
        console.warn('Geolocation permission error:', err);
        resolve({ allowed: false, reason: 'denied', error: err.message });
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 5000 }
    );
  });
}

