// YouTube Search (Supports Direct oEmbed + YouTube Public Scraping API)
async function performSearch() {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  const query = document.getElementById('query-input').value.trim();
  if (!query) return;

  const searchBtn = document.getElementById('search-btn');
  searchBtn.innerText = '...';
  searchBtn.disabled = true;

  const resultsList = document.getElementById('results-list');
  resultsList.innerHTML = '<div style="text-align: center; color: #94a3b8; font-size: 13px; padding: 20px;">מחפש שירים...</div>';

  try {
    // 1. If user pasted direct YouTube link
    if (query.includes('youtube.com') || query.includes('youtu.be')) {
      const res = await fetch(`https://noembed.com/embed?url=${encodeURIComponent(query)}`);
      const data = await res.json();
      if (data && data.title) {
        renderResults([{
          id: query,
          url: query,
          title: data.title,
          channel: data.author_name || 'YouTube',
          thumbnail: data.thumbnail_url || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150'
        }]);
        return;
      }
    }

    // 2. High-speed, official music search (supports Hebrew & English, zero CORS issues)
    const itunesUrl = `https://itunes.apple.com/search?term=${encodeURIComponent(query)}&media=music&entity=song&limit=15`;
    const resp = await fetch(itunesUrl);
    if (resp.ok) {
      const data = await resp.json();
      if (data && data.results && data.results.length > 0) {
        const cleanTracks = data.results.map(t => ({
          id: String(t.trackId),
          url: `ytsearch1:${t.artistName} ${t.trackName}`,
          title: `${t.artistName} - ${t.trackName}`,
          channel: t.collectionName || t.artistName,
          thumbnail: t.artworkUrl100 ? t.artworkUrl100.replace('100x100bb', '300x300bb') : 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150'
        }));
        renderResults(cleanTracks);
        return;
      }
    }
    fallbackMockSearch(query);
  } catch (err) {
    console.warn('Online search error, applying fallback', err);
    fallbackMockSearch(query);
  } finally {
    searchBtn.innerText = 'חפש';
    searchBtn.disabled = false;
  }
}

function fallbackMockSearch(query) {
  renderResults([
    {
      id: 'yt_1',
      url: `ytsearch1:${query}`,
      title: query,
      channel: 'YouTube Audio',
      thumbnail: 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=150'
    }
  ]);
}

function renderResults(tracks) {
  const container = document.getElementById('results-list');
  if (!tracks.length) {
    container.innerHTML = '<div style="text-align: center; color: #94a3b8; font-size: 13px; padding: 20px;">לא נמצאו תוצאות. נסו חיפוש אחר.</div>';
    return;
  }

  container.innerHTML = tracks.map((t, idx) => `
    <div class="result-item">
      <img src="${t.thumbnail}" class="result-thumb" alt="" />
      <div class="result-info">
        <div class="result-title" title="${t.title}">${t.title}</div>
        <div class="result-channel">${t.channel}</div>
      </div>
      <button class="request-btn" onclick='openModal(${JSON.stringify(t)})'>בקש שיר</button>
    </div>
  `).join('');
}

function openModal(track) {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  selectedTrack = track;
  document.getElementById('modal-thumb').src = track.thumbnail;
  document.getElementById('modal-title').innerText = track.title;
  document.getElementById('modal-channel').innerText = track.channel;
  document.getElementById('request-modal').style.display = 'flex';
}

