    0x00, 0x06, 0x70, 0x75, 0x62, 0x31, 0x31, 0x31
  ]);
  ws.send(connectPacket);
};

ws.onmessage = async (event) => {
  const buf = Buffer.from(await event.data.arrayBuffer());
  const type = buf[0] >> 4;
  if (type === 2) {
    const topic = "onyx/status/SHAZZ-6217";
    const payload = JSON.stringify({
      active: true,
      room: "SHAZZ-6217",
      djNames: "DJ Shazz & DJ Sonic",
      timestamp: Date.now()
    });
    // Publish packet with retain=true (header 0x31 = 0011 0001 -> type 3, QoS 0, retain 1)
    const topicBuf = Buffer.from(topic);
    const payloadBuf = Buffer.from(payload);
    const varHeader = Buffer.concat([
      Buffer.from([0x00, topicBuf.length]),
      topicBuf
    ]);
    const remainingLen = varHeader.length + payloadBuf.length;
    const pubPacket = Buffer.concat([
      Buffer.from([0x31, remainingLen]),
      varHeader,
      payloadBuf
    ]);
    ws.send(pubPacket);
    console.log("Published active: true with retain=true to HiveMQ!");
    setTimeout(() => { ws.close(); process.exit(0); }, 500);
  }
};
'

