// Global Event Room State
let isRoomActive = true;
let mqttStatusClient = null;
let sseClient = null;
let lastAppliedTimestamp = 0;
const pageStartTime = Date.now();
const isExplicitlyLive = urlParams.get('live') === 'true';

// ========================================================
// UNIFIED STATUS APPLIER (INSTANT PROACTIVE TRANSITION)
// ========================================================
function applyRoomStatus(statusInfo) {
  if (!statusInfo || typeof statusInfo.active !== 'boolean') return;
  const msgTime = Number(statusInfo.timestamp) || 0;

  // 1. Stale Message Guard:
  // If the guest scanned a QR code that explicitly has live=true,
  // reject any CLOSED (active: false) message that was created BEFORE this page was opened!
  if (isExplicitlyLive && statusInfo.active === false) {
    if (msgTime > 0 && msgTime < pageStartTime - 3000) {
      console.warn('[Room Status] Ignored stale CLOSED message (created before QR code was opened):', msgTime, '<', pageStartTime);
      return;
    }
  }

  // 2. Reject older out-of-order messages:
  if (msgTime > 0 && msgTime < lastAppliedTimestamp) {
    console.warn('[Room Status] Ignored older out-of-order message:', msgTime, '<', lastAppliedTimestamp);
    return;
  }
  if (msgTime > 0) {
    lastAppliedTimestamp = msgTime;
  }

  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'none';

  if (statusInfo.active === false) {
    if (isRoomActive !== false) {
      console.log('[Room Status Event] Station closed by DJ -> Locking screen proactively');
      isRoomActive = false;
      showClosedState({ reason: 'inactive', djName: statusInfo.djNames });
    }
  } else if (statusInfo.active === true) {
    if (isRoomActive !== true) {
      console.log('[Room Status Event] Station opened by DJ -> Showing request screen');
      isRoomActive = true;
      showActiveState(statusInfo);
    }
  }
}

// 1. REAL-TIME SERVER-SENT EVENTS (SSE) via NTFY (PORT 443 HTTPS - ZERO BLOCKING)
