// Global Event Room State
let isRoomActive = true;
let mqttStatusClient = null;
let sseClient = null;

// ========================================================
// UNIFIED STATUS APPLIER (INSTANT PROACTIVE TRANSITION)
// ========================================================
function applyRoomStatus(statusInfo) {
  if (!statusInfo || typeof statusInfo.active !== 'boolean') return;

  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'none';

  if (statusInfo.active === false) {
    if (isRoomActive !== false) {
      console.log('[Room Status Event] Station closed by DJ -> Locking screen proactively');
      isRoomActive = false;
      showClosedState({ reason: 'inactive', djName: statusInfo.djNames });
    }
  } else if (statusInfo.active === true) {
    if (isRoomActive !== true) {
      console.log('[Room Status Event] Station opened by DJ -> Showing request screen');
      isRoomActive = true;
      showActiveState(statusInfo);
    }
  }
}

// 1. REAL-TIME SERVER-SENT EVENTS (SSE) via NTFY (PORT 443 HTTPS - ZERO BLOCKING)
function initSseStatusListener() {
  try {
    const sseUrl = `https://ntfy.sh/onyx_status_${cleanRoom.toLowerCase()}/sse`;
    sseClient = new EventSource(sseUrl);
