          const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
          applyRoomStatus(payload);
        }
      } catch(e) {}
    };
    sseClient.onerror = () => {
      pollStatusHttp();
    };

    if (cleanRoom !== 'SHAZZ-SONIC') {
      const fallbackSource = new EventSource('https://ntfy.sh/onyx_status_shazz-sonic/sse');
      fallbackSource.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.event === 'message') {
            const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
            applyRoomStatus(payload);
          }
        } catch(e) {}
      };
    }
  } catch (err) {
    console.warn('[SSE] EventSource init error:', err);
  }
}

// 2. ACTIVE FAST HTTP POLLING (EVERY 2.5s OVER STANDARD HTTPS 443)
async function pollStatusHttp() {
  const tryFetch = async (target) => {
    try {
      const res = await fetch(`https://ntfy.sh/onyx_status_${target.toLowerCase()}/json?poll=1`, {
        cache: 'no-store',
