const isDjGpsMode = urlParams.get('dj_gps') === 'true' || urlParams.get('dj_gps') === '1';

async function captureAndSendDjGps() {
  const btn = document.getElementById('dj-gps-trigger-btn');
  const box = document.getElementById('dj-gps-status-box');
  if (!btn || !box) return;

  btn.disabled = true;
  btn.innerText = 'דוגם מיקום GPS לווייני... 🛰️';
  box.style.display = 'block';
  box.innerHTML = 'ממתין לקריאת לווייני GPS מהמכשיר...';

  if (!navigator.geolocation) {
    box.innerHTML = '❌ הדפדפן אינו תומך ב-GPS.';
    btn.disabled = false;
    btn.innerText = 'נסה שוב 🔄';
    return;
  }

  navigator.geolocation.getCurrentPosition(
    async (pos) => {
      const lat = parseFloat(pos.coords.latitude.toFixed(6));
      const lon = parseFloat(pos.coords.longitude.toFixed(6));
      const accuracy = Math.round(pos.coords.accuracy || 5);
      box.innerHTML = `🛰️ נדגם מיקום GPS: <b>${lat}, ${lon}</b> (דיוק: ±${accuracy} מטר)<br/>משדר למחשב...`;

      const payload = {
        lat: lat,
        lon: lon,
        accuracy: accuracy,
        timestamp: Date.now(),
        room: cleanRoom
      };

      // 1. Send via HTTPS ntfy (port 443)
      try {
        await fetch(`https://ntfy.sh/onyx_dj_location_${cleanRoom.toLowerCase()}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      } catch(e) {}

      // 2. Send via MQTT
      try {
        await sendViaMqtt('onyx/dj_location/' + cleanRoom, payload);
      } catch(e) {}

      box.style.background = 'rgba(16, 185, 129, 0.15)';
      box.style.borderColor = 'rgba(16, 185, 129, 0.4)';
      box.style.color = '#34d399';
      box.innerHTML = `✅ <b>המיקום נקלט בהצלחה במחשב!</b><br/>קואורדינטות: ${lat}, ${lon} (דיוק: ±${accuracy} מ')<br/>רדיוס המסיבה מכויל כעת סביב עמדה זו. אפשר לסגור חלון זה.`;
      btn.style.background = '#059669';
      btn.innerText = 'העמדה עודכנה בהצלחה! 🎉';
    },
    (err) => {
      box.style.background = 'rgba(239, 68, 68, 0.15)';
      box.style.borderColor = 'rgba(239, 68, 68, 0.4)';
      box.style.color = '#f87171';
      box.innerHTML = `❌ שגיאה בקבלת מיקום: ${err.message}<br/>ודא שאישרת גישה למיקום (Location Services) בספארי.`;
      btn.disabled = false;
      btn.innerText = 'נסה שוב 🔄';
    },
    { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 }
  );
}

// Monitor Event Status & Location
async function checkStatus() {
  const loadScreen = document.getElementById('loading-screen');
  if (loadScreen) loadScreen.style.display = 'flex';

  // 0. DJ GPS Calibration Mode from Phone:
  if (isDjGpsMode) {
    if (loadScreen) loadScreen.style.display = 'none';
    document.getElementById('state-closed').style.display = 'none';
    document.getElementById('state-active').style.display = 'none';
    const djGpsContainer = document.getElementById('state-dj-gps');
    if (djGpsContainer) djGpsContainer.style.display = 'flex';
    const badge = document.getElementById('dj-gps-room-badge');
    if (badge) badge.innerText = `• חדר: ${cleanRoom}`;
    return;
  }

  // 1. Explicitly closed in URL query param:
  if (urlParams.get('closed') === 'true') {
    isRoomActive = false;
    if (loadScreen) loadScreen.style.display = 'none';
    showClosedState({ reason: 'inactive' });
    return;
  }

