}, [reclaimableMemMb]);

const projectedFreeGb = useMemo(() => {
  const additionalGb = reclaimableMemMb / 1024;
  return (sysMem.free_gb + additionalGb).toFixed(1);
}, [sysMem.free_gb, reclaimableMemMb]);

