let currentSearchResults = [];

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// High-Speed Search (YouTube Innertube + Vercel Serverless + Apple Fallback)
async function performSearch() {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  const query = document.getElementById('query-input').value.trim();
  if (!query) return;

  const searchBtn = document.getElementById('search-btn');
  searchBtn.innerText = '...';
  searchBtn.disabled = true;

  const resultsList = document.getElementById('results-list');
  resultsList.innerHTML = '<div style="text-align: center; color: #94a3b8; font-size: 13px; padding: 20px;">מחפש שירים ברשת... 🎧</div>';

  try {
    // 1. Direct YouTube link pasted by guest
    if (query.includes('youtube.com') || query.includes('youtu.be')) {
      try {
        const res = await fetch(`https://noembed.com/embed?url=${encodeURIComponent(query)}`);
        if (res.ok) {
          const data = await res.json();
          if (data && data.title) {
            renderResults([{
              id: query,
              url: query,
              title: data.title,
              channel: data.author_name || 'YouTube',
              thumbnail: data.thumbnail_url || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150',
              duration: ''
            }]);
            return;
          }
        }
      } catch(e) {}
    }

    // 2. High-speed YouTube Search via same-origin Vercel Serverless Function
    try {
      const apiResp = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
      if (apiResp.ok) {
        const apiData = await apiResp.json();
        if (apiData && Array.isArray(apiData.results) && apiData.results.length > 0) {
          renderResults(apiData.results);
          return;
        }
      }
    } catch(apiErr) {
      console.warn('/api/search error, falling back:', apiErr);
    }

    // 3. Fallback: Apple iTunes API (Direct client fallback with Israel store)
    try {
      const itunesUrl = `https://itunes.apple.com/search?term=${encodeURIComponent(query)}&media=music&entity=song&limit=15&country=IL`;
      const resp = await fetch(itunesUrl);
      if (resp.ok) {
        const data = await resp.json();
        if (data && data.results && data.results.length > 0) {
          const cleanTracks = data.results.map(t => ({
            id: String(t.trackId),
            url: `ytsearch1:${t.artistName} ${t.trackName}`,
            title: `${t.artistName} - ${t.trackName}`,
            channel: t.collectionName || t.artistName,
            thumbnail: t.artworkUrl100 ? t.artworkUrl100.replace('100x100bb', '300x300bb') : 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150',
            duration: ''
          }));
          renderResults(cleanTracks);
          return;
        }
      }
    } catch(itunesErr) {
      console.warn('iTunes fallback error:', itunesErr);
    }

    fallbackMockSearch(query);
  } catch (err) {
    console.warn('Search error, applying fallback', err);
    fallbackMockSearch(query);
  } finally {
    searchBtn.innerText = 'חפש';
    searchBtn.disabled = false;
  }
}

function fallbackMockSearch(query) {
  renderResults([
    {
      id: 'yt_1',
      url: `ytsearch1:${query}`,
      title: query,
      channel: 'חיפוש ישיר ביוטיוב',
      thumbnail: 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=150',
      duration: ''
    }
  ]);
}

function renderResults(tracks) {
  currentSearchResults = Array.isArray(tracks) ? tracks : [];
  const container = document.getElementById('results-list');
  if (!currentSearchResults.length) {
    container.innerHTML = '<div style="text-align: center; color: #94a3b8; font-size: 13px; padding: 20px;">לא נמצאו תוצאות. נסו חיפוש אחר.</div>';
    return;
  }

  container.innerHTML = currentSearchResults.map((t, idx) => {
    const safeTitle = escapeHtml(t.title || 'שיר ללא כותרת');
    const safeChannel = escapeHtml(t.channel || 'YouTube');
    const thumb = escapeHtml(t.thumbnail || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150');
    const durationTag = t.duration ? `<span class="thumb-duration">${escapeHtml(t.duration)}</span>` : '';

    return `
    <div class="result-item">
      <div style="position: relative; flex-shrink: 0; width: 76px; height: 52px;">
        <img src="${thumb}" class="result-thumb" alt="" onerror="this.onerror=null;this.src='https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=150';" />
        ${durationTag}
      </div>
      <div class="result-info">
        <div class="result-title" title="${safeTitle}">${safeTitle}</div>
        <div class="result-channel">${safeChannel}</div>
      </div>
      <button class="request-btn" onclick="openModalByIndex(${idx})">בקש שיר</button>
    </div>
  `;
  }).join('');
}

function openModalByIndex(idx) {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  const track = currentSearchResults[idx];
  if (!track) return;
  openModal(track);
}

function openModal(track) {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  selectedTrack = track;
  document.getElementById('modal-thumb').src = track.thumbnail;
  document.getElementById('modal-title').innerText = track.title;
  document.getElementById('modal-channel').innerText = track.channel;
  document.getElementById('request-modal').style.display = 'flex';
}

