import subprocess, time, re, json

def get_wireless_screens():
    screens = []

    # 1. Discover GoogleCast
    try:
        p = subprocess.Popen(['dns-sd', '-B', '_googlecast._tcp', '.'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        time.sleep(1.0)
        p.terminate()
        out, _ = p.communicate()
        cast_instances = []
        for line in out.splitlines():
            if 'Add' in line:
                parts = line.split()
                if len(parts) >= 7:
                    name = ' '.join(parts[6:])
                    if name not in cast_instances:
                        cast_instances.append(name)

        for inst in cast_instances:
            p_res = subprocess.Popen(['dns-sd', '-L', inst, '_googlecast._tcp', '.'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            time.sleep(0.8)
            p_res.terminate()
            res_out, _ = p_res.communicate()

            fn_match = re.search(r'fn=([^\r\n]+?)(?:\s+[a-z]{2}=|$)', res_out)
            if fn_match:
                raw_fn = fn_match.group(1)
                friendly_name = raw_fn.replace('\\ ', ' ').replace('\\–', '–').replace('\\-', '-').strip()
            else:
                friendly_name = inst

            md_match = re.search(r'md=([^\s]+)', res_out)
            model = md_match.group(1) if md_match else 'Google Cast / Smart TV'

            screens.append({
                'id': f'cast_{inst}',
                'name': friendly_name,
                'model': model,
                'type': 'tv',
                'protocol': 'Google Cast',
                'status': 'ready'
            })
    except Exception as e:
        print('Cast scan error:', e)

    # 2. Discover AirPlay
    try:
        p = subprocess.Popen(['dns-sd', '-B', '_airplay._tcp', '.'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        time.sleep(1.0)
        p.terminate()
        out, _ = p.communicate()
        airplay_instances = []
        for line in out.splitlines():
            if 'Add' in line:
                parts = line.split()
                if len(parts) >= 7:
                    name = ' '.join(parts[6:])
                    clean_name = name.replace('\\ ', ' ')
                    if clean_name not in airplay_instances:
                        airplay_instances.append(clean_name)

        for inst in airplay_instances:
            screens.append({
                'id': f'airplay_{inst}',
                'name': inst,
                'model': 'AirPlay 2 / Apple TV',
                'type': 'apple_tv',
                'protocol': 'AirPlay',
                'status': 'ready'
            })
    except Exception as e:
        print('AirPlay scan error:', e)

    return screens

print(json.dumps(get_wireless_screens(), ensure_ascii=False, indent=2))
