  <script>
    const urlParams = new URLSearchParams(window.location.search);
    const roomCode = (urlParams.get('room') || 'SHAZZ-SONIC').toUpperCase().replace(/[^A-Z0-9_-]/g, '') || 'SHAZZ-SONIC';
    const djNames = urlParams.get('dj') || 'DJ Shazz & DJ Sonic';

    document.getElementById('room-badge-text').innerText = `עמדת בקשות שירים בלייב • חדר ${roomCode}`;
    document.getElementById('dj-names-text').innerText = djNames;

    // Construct target URL for guests
    const guestUrl = `${window.location.origin}/?room=${encodeURIComponent(roomCode)}&live=true`;

    // Render QR Code
    new QRCode(document.getElementById("qrcode"), {
      text: guestUrl,
      width: 320,
      height: 320,
      colorDark: "#07020d",
      colorLight: "#ffffff",
      correctLevel: QRCode.CorrectLevel.H
    });

    // Realtime Stage Spotlight Glide Transitions
    let isQrCorner = false;
    function glideQrToCorner() {
      isQrCorner = true;
      const qr = document.getElementById('stage-qr-card');
      if (!qr) return;
      const rect = qr.getBoundingClientRect();
      const currentX = rect.left;
      const currentY = rect.top;
      const targetX = 32;
      const targetY = 32;
      const deltaX = targetX - currentX;
      const deltaY = targetY - currentY;

      qr.style.transform = `translate(${deltaX}px, ${deltaY}px) scale(0.62)`;
    }

    function glideQrToCenter() {
      isQrCorner = false;
      const qr = document.getElementById('stage-qr-card');
      if (!qr) return;
      qr.style.transform = 'translate(0px, 0px) scale(1)';
    }

    window.addEventListener('resize', () => {
      if (isQrCorner) {
        glideQrToCenter();
        requestAnimationFrame(() => glideQrToCorner());
      }
    });

    function activateSpotlight(data) {
      document.body.classList.add('spotlight-mode');

      // Update texts
      document.getElementById('spotlight-title').innerText = data.songTitle || 'שיר לבקשת הקהל';
      document.getElementById('spotlight-requester').innerText = data.requester || 'אורח ברחבה';

      const noteBox = document.getElementById('spotlight-note-box');
      const noteText = document.getElementById('spotlight-note');
      if (data.note && data.note.trim()) {
        noteText.innerText = data.note;
        noteBox.style.display = 'flex';
      } else {
        noteBox.style.display = 'none';
      }

      // Update photo / backdrop
      const backdrop = document.getElementById('spotlight-backdrop');
      const photoImg = document.getElementById('spotlight-img');
      if (data.photo) {
        photoImg.src = data.photo;
        photoImg.style.display = 'block';
      } else {
        photoImg.src = '';
        photoImg.style.display = 'none';
      }
      backdrop.classList.add('active');

      // Activate card
      document.getElementById('spotlight-card').classList.add('active');

      // Smoothly glide QR code to top-left corner
      glideQrToCorner();
    }

    function deactivateSpotlight() {
      document.body.classList.remove('spotlight-mode');
      document.getElementById('spotlight-backdrop').classList.remove('active');
      document.getElementById('spotlight-card').classList.remove('active');

      // Glide QR code back to center
      glideQrToCenter();
    }

    function handleSpotlightMessage(payload) {
      if (payload && payload.active) {
        activateSpotlight(payload);
      } else {
        deactivateSpotlight();
      }
    }

    // Realtime MQTT Listener for incoming requests & live stage spotlight
    function initMqttListener() {
      try {
        const clientId = 'stage_' + Math.random().toString(36).substring(2, 9);
        const client = new Paho.MQTT.Client('broker.hivemq.com', 8884, '/mqtt', clientId);

        client.onMessageArrived = (message) => {
          try {
            const payload = JSON.parse(message.payloadString);
            if (message.destinationName && message.destinationName.includes('spotlight')) {
              handleSpotlightMessage(payload);
            } else if (payload && payload.title) {
              showToast(payload);
            }
          } catch(e) {}
        };

        client.connect({
          useSSL: true,
          timeout: 5,
          cleanSession: true,
          onSuccess: () => {
            console.log('Stage screen subscribed to MQTT topics');
            client.subscribe(`onyx/requests/${roomCode}`, { qos: 0 });
            client.subscribe(`onyx/stage/${roomCode}/spotlight`, { qos: 0 });
          },
          onFailure: () => {
            setTimeout(initMqttListener, 4000);
          }
        });
      } catch(err) {
        console.warn('MQTT stage connect err:', err);
      }
    }

    // LocalStorage fallback for same-machine testing
    window.addEventListener('storage', (e) => {
      if (e.key === 'onyx_stage_spotlight') {
        try {
          if (e.newValue) {
            handleSpotlightMessage(JSON.parse(e.newValue));
          } else {
            handleSpotlightMessage({ active: false });
          }
        } catch(err) {}
      }
    });

