  border-radius: 50%;
  background: rgba(0, 0, 0, 0.8);
  color: #f43f5e;
  border: 1px solid rgba(244, 63, 94, 0.6);
  font-size: 13px;
  font-weight: 900;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 30;
}

/* 16:9 Interactive Stage Simulator */
.stage-simulator-wrap {
  margin-top: 12px;
  background: #0d0615;
  border: 1.5px solid rgba(245, 158, 11, 0.4);
  border-radius: 16px;
  padding: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
}
.stage-sim-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  font-weight: 800;
  color: #facc15;
  margin-bottom: 8px;
  padding: 0 2px;
}
.stage-sim-screen {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #05020a;
  border-radius: 12px;
  overflow: hidden;
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  touch-action: none;
  user-select: none;
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
}
.stage-sim-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.65) contrast(1.1);
}
.stage-sim-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(5,2,10,0.15) 20%, rgba(5,2,10,0.85) 90%);
  pointer-events: none;
}
.stage-sim-qr-badge {
  position: absolute;
  top: 6px;
  left: 6px;
  background: #ffffff;
  color: #05020a;
  padding: 3px 6px;
  border-radius: 6px;
  font-size: 9px;
  font-weight: 900;
  box-shadow: 0 2px 8px rgba(0,0,0,0.8);
  pointer-events: none;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 3px;
}
/* Draggable Card in Simulator */
.stage-sim-draggable {
  position: absolute;
  top: 75%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(15, 7, 26, 0.92);
  border: 1.5px solid rgba(245, 158, 11, 0.7);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.85), 0 0 15px rgba(245, 158, 11, 0.35);
  backdrop-filter: blur(10px);
  border-radius: 12px;
  padding: 6px 12px;
  text-align: center;
  cursor: grab;
  touch-action: none;
  z-index: 20;
  max-width: 82%;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.stage-sim-draggable.dragging {
  cursor: grabbing;
  box-shadow: 0 0 25px rgba(245, 158, 11, 0.9);
  border-color: #fbbf24;
  transform: translate(-50%, -50%) scale(1.04);
}
.sim-song-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 800;
  color: #fef08a;
  background: rgba(245, 158, 11, 0.15);
  padding: 2px 7px;
  border-radius: 6px;
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.sim-requester-text {
  font-size: 11px;
  font-weight: 900;
  color: #38bdf8;
  margin-top: 2px;
  text-shadow: 0 0 8px rgba(56, 189, 248, 0.5);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sim-note-text {
  font-size: 10px;
  font-weight: 700;
  color: #ffffff;
  font-style: italic;
  margin-top: 1px;
  line-height: 1.25;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.drag-hint-badge {
  font-size: 8px;
  color: #94a3b8;
  font-weight: 800;
  margin-top: 3px;
  letter-spacing: 0.5px;
}
.sim-preset-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 8px;
}
.sim-preset-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #e2e8f0;
  border-radius: 8px;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
}
.sim-preset-btn:hover, .sim-preset-btn:active {
  background: rgba(245, 158, 11, 0.25);
  border-color: #f59e0b;
  color: #fbbf24;
}

