let selectedPhotoDataUrl = null;
let selectedTextPosition = { x: 50, y: 75 }; // Default lower center to clear faces

function updateSimContent() {
  const songEl = document.getElementById('sim-song-text');
  const reqEl = document.getElementById('sim-requester-text');
  const noteEl = document.getElementById('sim-note-text');
  const noteWrap = document.getElementById('sim-note-wrap');

  if (songEl && selectedTrack) {
    songEl.innerText = selectedTrack.title;
  }
  const nameVal = document.getElementById('requester-name')?.value.trim();
  if (reqEl) {
    reqEl.innerText = nameVal ? `הוקדש על ידי: ${nameVal}` : 'הוקדש על ידי: אורח ברחבה';
  }
  const noteVal = document.getElementById('requester-note')?.value.trim();
  if (noteEl && noteWrap) {
    if (noteVal) {
      noteEl.innerText = `"${noteVal}"`;
      noteWrap.style.display = 'block';
    } else {
      noteEl.innerText = '';
      noteWrap.style.display = 'none';
    }
  }
}

function setSimPosition(x, y) {
  selectedTextPosition = { x: Math.round(x), y: Math.round(y) };
  const card = document.getElementById('stage-sim-draggable');
  if (card) {
    card.style.left = `${selectedTextPosition.x}%`;
    card.style.top = `${selectedTextPosition.y}%`;
  }
}

let isDraggingSim = false;
let dragStartX = 0;
let dragStartY = 0;
let cardStartLeft = 50;
let cardStartTop = 75;

function initSimDrag() {
  const card = document.getElementById('stage-sim-draggable');
  const screen = document.getElementById('stage-sim-screen');
  if (!card || !screen || card._dragInitialized) return;
  card._dragInitialized = true;

  const onStart = (clientX, clientY) => {
    isDraggingSim = true;
    dragStartX = clientX;
    dragStartY = clientY;
    cardStartLeft = selectedTextPosition.x;
    cardStartTop = selectedTextPosition.y;
    card.classList.add('dragging');
  };

  const onMove = (clientX, clientY) => {
    if (!isDraggingSim) return;
    const rect = screen.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) return;

    const deltaXPercent = ((clientX - dragStartX) / rect.width) * 100;
    const deltaYPercent = ((clientY - dragStartY) / rect.height) * 100;

    let newX = Math.round(cardStartLeft + deltaXPercent);
    let newY = Math.round(cardStartTop + deltaYPercent);

    // Clamping boundaries so card remains visible inside screen
    newX = Math.max(22, Math.min(78, newX));
    newY = Math.max(20, Math.min(80, newY));

    // If user drags directly into top-left QR badge, nudge slightly down
    if (newX < 34 && newY < 32) {
      newY = 34;
    }

    selectedTextPosition = { x: newX, y: newY };
    card.style.left = `${newX}%`;
    card.style.top = `${newY}%`;
  };

  const onEnd = () => {
    if (isDraggingSim) {
      isDraggingSim = false;
      card.classList.remove('dragging');
    }
  };

  // Touch events (Mobile)
  card.addEventListener('touchstart', (e) => {
    if (e.touches && e.touches.length === 1) {
      onStart(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: true });

  window.addEventListener('touchmove', (e) => {
    if (isDraggingSim && e.touches && e.touches.length === 1) {
      onMove(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: true });

  window.addEventListener('touchend', onEnd);

  // Mouse events (Desktop)
  card.addEventListener('mousedown', (e) => {
    e.preventDefault();
    onStart(e.clientX, e.clientY);
  });

  window.addEventListener('mousemove', (e) => {
    if (isDraggingSim) {
      onMove(e.clientX, e.clientY);
    }
  });

  window.addEventListener('mouseup', onEnd);
}

function openModal(track) {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  selectedTrack = track;
  document.getElementById('modal-thumb').src = track.thumbnail;
  document.getElementById('modal-title').innerText = track.title;
  document.getElementById('modal-channel').innerText = track.channel;
  document.getElementById('request-modal').style.display = 'flex';

  setSimPosition(50, 75);
  updateSimContent();
  initSimDrag();

  const nameInput = document.getElementById('requester-name');
  const noteInput = document.getElementById('requester-note');
  if (nameInput) nameInput.oninput = updateSimContent;
  if (noteInput) noteInput.oninput = updateSimContent;
}

function handlePhotoSelected(input) {
  const file = input && input.files && input.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      // Downscale to max 1280px on largest dimension for lightweight ~60-80KB transfer
      const maxDim = 1280;
      let w = img.width;
      let h = img.height;
      if (w > maxDim || h > maxDim) {
        if (w > h) {
          h = Math.round((h * maxDim) / w);
          w = maxDim;
        } else {
          w = Math.round((w * maxDim) / h);
          h = maxDim;
        }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);

      selectedPhotoDataUrl = canvas.toDataURL('image/jpeg', 0.82);
      const simBg = document.getElementById('stage-sim-bg');
      const simWrap = document.getElementById('stage-simulator-wrap');
      const actionsBtns = document.getElementById('photo-actions-btns');

      if (simBg) simBg.src = selectedPhotoDataUrl;
      if (simWrap) simWrap.style.display = 'block';
      if (actionsBtns) actionsBtns.style.display = 'none';

      updateSimContent();
      initSimDrag();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function removeSelectedPhoto() {
  selectedPhotoDataUrl = null;
  selectedTextPosition = { x: 50, y: 75 };
  const cam = document.getElementById('photo-camera-input');
  const gal = document.getElementById('photo-gallery-input');
  if (cam) cam.value = '';
  if (gal) gal.value = '';
  const simWrap = document.getElementById('stage-simulator-wrap');
  if (simWrap) simWrap.style.display = 'none';
  const simBg = document.getElementById('stage-sim-bg');
  if (simBg) simBg.src = '';
  const actionsBtns = document.getElementById('photo-actions-btns');
  if (actionsBtns) actionsBtns.style.display = 'flex';
}

function closeModal() {
  document.getElementById('request-modal').style.display = 'none';
  selectedTrack = null;
  removeSelectedPhoto();
  const nameInput = document.getElementById('requester-name');
  const noteInput = document.getElementById('requester-note');
  if (nameInput) nameInput.value = '';
  if (noteInput) noteInput.value = '';
}

