+    function setSimPosition(x, y) {
+      selectedTextPosition = { x: Math.round(x), y: Math.round(y) };
+      const card = document.getElementById('stage-sim-draggable');
+      if (card) {
+        card.style.left = `${selectedTextPosition.x}%`;
+        card.style.top = `${selectedTextPosition.y}%`;
+      }
+    }
+
+    let isDraggingSim = false;
+    let dragStartX = 0;
+    let dragStartY = 0;
+    let cardStartLeft = 50;
+    let cardStartTop = 75;
+
+    function initSimDrag() {
+      const card = document.getElementById('stage-sim-draggable');
+      const screen = document.getElementById('stage-sim-screen');
+      if (!card || !screen || card._dragInitialized) return;
+      card._dragInitialized = true;
+
+      const onStart = (clientX, clientY) => {
+        isDraggingSim = true;
+        dragStartX = clientX;
+        dragStartY = clientY;
+        cardStartLeft = selectedTextPosition.x;
+        cardStartTop = selectedTextPosition.y;
+        card.classList.add('dragging');
+      };
+
+      const onMove = (clientX, clientY) => {
+        if (!isDraggingSim) return;
+        const rect = screen.getBoundingClientRect();
+        if (rect.width === 0 || rect.height === 0) return;
+
+        const deltaXPercent = ((clientX - dragStartX) / rect.width) * 100;
+        const deltaYPercent = ((clientY - dragStartY) / rect.height) * 100;
+
+        let newX = Math.round(cardStartLeft + deltaXPercent);
+        let newY = Math.round(cardStartTop + deltaYPercent);
+
+        // Clamping boundaries so card remains visible inside screen
+        newX = Math.max(22, Math.min(78, newX));
+        newY = Math.max(20, Math.min(80, newY));
+
+        // If user drags directly into top-left QR badge, nudge slightly down
+        if (newX < 34 && newY < 32) {
+          newY = 34;
+        }
+
+        selectedTextPosition = { x: newX, y: newY };
+        card.style.left = `${newX}%`;
+        card.style.top = `${newY}%`;
+      };
+
+      const onEnd = () => {
+        if (isDraggingSim) {
+          isDraggingSim = false;
+          card.classList.remove('dragging');
+        }
+      };
+
+      // Touch events (Mobile)
+      card.addEventListener('touchstart', (e) => {
+        if (e.touches && e.touches.length === 1) {
+          onStart(e.touches[0].clientX, e.touches[0].clientY);
+        }
+      }, { passive: true });
+
+      window.addEventListener('touchmove', (e) => {
+        if (isDraggingSim && e.touches && e.touches.length === 1) {
+          onMove(e.touches[0].clientX, e.touches[0].clientY);
+        }
+      }, { passive: true });
+
+      window.addEventListener('touchend', onEnd);
+
+      // Mouse events (Desktop)
+      card.addEventListener('mousedown', (e) => {
+        e.preventDefault();
+        onStart(e.clientX, e.clientY);
+      });
+
+      window.addEventListener('mousemove', (e) => {
+        if (isDraggingSim) {
+          onMove(e.clientX, e.clientY);
+        }
+      });
+
+      window.addEventListener('mouseup', onEnd);
+    }
