args.ReplacementContent:
let guestDistance = 0;
let selectedTrack = null;
let roomRef = null;

// ========================================================
// FIRST-TIME EVENT STAGE & PRIVACY CONSENT LOGIC (ONE-TIME PER EVENT)
// ========================================================
let isConsentChecked = false;

function getEventConsentKey() {
  return 'onyx_stage_consent_' + cleanRoom;
}

function checkConsentModal() {
  const agreed = localStorage.getItem(getEventConsentKey()) === 'true';
  const modal = document.getElementById('consent-modal');
  const closeBtn = document.getElementById('consent-close-btn');
  if (!modal) return;
  if (!agreed) {
    isConsentChecked = false;
    updateConsentCheckboxUI();
    if (closeBtn) closeBtn.style.display = 'none'; // Force approval on first visit
    modal.style.display = 'flex';
  } else {
    modal.style.display = 'none';
  }
}

function openConsentModal() {
  const modal = document.getElementById('consent-modal');
  const closeBtn = document.getElementById('consent-close-btn');
  const agreed = localStorage.getItem(getEventConsentKey()) === 'true';
  if (!modal) return;
  if (agreed) {
    isConsentChecked = true;
    updateConsentCheckboxUI();
    if (closeBtn) closeBtn.style.display = 'block';
  } else {
    isConsentChecked = false;
    updateConsentCheckboxUI();
    if (closeBtn) closeBtn.style.display = 'none';
  }
  modal.style.display = 'flex';
}

function closeConsentModal() {
  const modal = document.getElementById('consent-modal');
  if (modal) {
    modal.style.transition = 'opacity 0.25s ease';
    modal.style.opacity = '0';
    setTimeout(() => {
      modal.style.display = 'none';
      modal.style.opacity = '1';
    }, 250);
  }
}

function toggleConsentCheckbox() {
  isConsentChecked = !isConsentChecked;
  updateConsentCheckboxUI();
}

function updateConsentCheckboxUI() {
  const wrap = document.getElementById('consent-checkbox-wrap');
  const box = document.getElementById('consent-checkbox-custom');
  const btn = document.getElementById('consent-confirm-btn');
  if (!wrap || !box || !btn) return;

  if (isConsentChecked) {
    wrap.classList.add('checked');
    box.classList.add('checked');
    box.innerHTML = '<span style="font-size: 14px; font-weight: 900; line-height: 1;">✓</span>';
    btn.disabled = false;
  } else {
    wrap.classList.remove('checked');
    box.classList.remove('checked');
    box.innerHTML = '';
    btn.disabled = true;
  }
}

function confirmConsent() {
  if (!isConsentChecked) return;
  localStorage.setItem(getEventConsentKey(), 'true');
  closeConsentModal();
}

