                title="אשר את הבקשה והתחל הורדה מיידית למחשב"
              >
                <CheckCircle2 className="w-3.5 h-3.5" />
                <span>אשר והורד ✓</span>
              </button>

              <button
                onClick={() => handleRejectRequest(item)}
