.spotlight-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.55) contrast(1.15);
  transform: scale(1.02);
  transition: transform 14s ease-out;
}
.spotlight-backdrop.active .spotlight-img {
  transform: scale(1.12); /* Subtle Ken-Burns zoom */
}
.spotlight-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(5,2,10,0.2) 20%, rgba(5,2,10,0.85) 85%);
  box-shadow: inset 0 0 120px rgba(5,2,10,0.95);
}

/* Spotlight Dynamic Position Content Card */
.spotlight-card {
  position: fixed;
  left: 50%;
  top: 75%;
  transform: translate(-50%, -50%) scale(0.95);
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 1.2vw 2.2vw;
  border-radius: 2.2vw;
  background: rgba(10, 4, 18, 0.88);
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(20px);
  box-shadow: 0 1vw 3vw rgba(0, 0, 0, 0.85), 0 0 2vw rgba(168, 85, 247, 0.35);
  max-width: 75vw;
  width: max-content;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1), left 0.6s ease, top 0.6s ease;
}
.spotlight-card.active {
  opacity: 1;
  transform: translate(-50%, -50%) scale(var(--card-scale, 1));
  pointer-events: auto;
}

.spotlight-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4vw;
  padding: 0.3vw 1.1vw;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.18);
  border: 1.5px solid rgba(245, 158, 11, 0.6);
  color: #fbbf24;
  font-size: 1.2vw;
  font-weight: 900;
  letter-spacing: 0.5px;
  margin-bottom: 0.5vw;
  box-shadow: 0 0 2vw rgba(245, 158, 11, 0.3);
  animation: pulse 2s infinite;
  white-space: nowrap;
}

/* Song Title & Artist: responsive 1:1 scale */
.spotlight-title {
  font-family: 'Space Grotesk', 'Assistant', sans-serif;
  font-size: 2.1vw;
  font-weight: 800;
  background: linear-gradient(135deg, #ffffff 0%, #fef08a 40%, #f472b6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5vw;
  max-width: 68vw;
  line-height: 1.25;
  text-shadow: 0 0 1.5vw rgba(244, 114, 182, 0.35);
  direction: rtl;
  unicode-bidi: plaintext;
}

.spotlight-requester-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4vw;
  font-size: 1.3vw;
  font-weight: 800;
  color: #e2e8f0;
  margin-bottom: 0.5vw;
  background: rgba(15, 7, 26, 0.65);
  padding: 0.35vw 1.2vw;
  border-radius: 1.2vw;
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(14px);
  white-space: nowrap;
  direction: rtl;
}
.spotlight-requester {
  color: #38bdf8;
  font-weight: 900;
  text-shadow: 0 0 1vw rgba(56, 189, 248, 0.6);
}

.spotlight-note-box {
  max-width: 65vw;
  background: rgba(18, 10, 31, 0.85);
  border: 1.5px solid rgba(245, 158, 11, 0.45);
  padding: 0.4vw 1.2vw;
  border-radius: 1.4vw;
  backdrop-filter: blur(20px);
  box-shadow: 0 1vw 2.5vw rgba(0, 0, 0, 0.6), 0 0 2vw rgba(245, 158, 11, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4vw;
  direction: rtl;
}
.quote-mark {
  font-size: 2.2vw;
  line-height: 1;
  color: #f59e0b;
  font-family: serif;
  opacity: 0.8;
}
.spotlight-note {
  font-size: 1.2vw;
  font-weight: 700;
  color: #fff;
  line-height: 1.25;
  font-style: italic;
  direction: rtl;
  unicode-bidi: plaintext;
}

