args.ReplacementContent:
  // Update photo / backdrop with smooth dual-buffer crossfade
  updateSpotlightPhoto(data.photo);
  document.getElementById('spotlight-backdrop').classList.add('active');

  // Activate card and apply dynamic textPosition and textScale from guest request
  const card = document.getElementById('spotlight-card');
  const posX = (data.textPosition && typeof data.textPosition.x === 'number') ? data.textPosition.x : 50;
  const posY = (data.textPosition && typeof data.textPosition.y === 'number') ? data.textPosition.y : 75;
  const scale = (typeof data.textScale === 'number' && data.textScale > 0) ? data.textScale : 1.0;
  card.style.left = `${posX}%`;
  card.style.top = `${posY}%`;
  card.style.setProperty('--card-scale', scale);
  card.classList.add('active');

  // Smoothly glide QR code to top-left corner
  glideQrToCorner();
}

let currentPhotoSlot = 'a';
let currentPhotoUrl = '';

function updateSpotlightPhoto(newPhotoUrl) {
  const imgA = document.getElementById('spotlight-img-a');
  const imgB = document.getElementById('spotlight-img-b');
  if (!imgA || !imgB) return;

  if (!newPhotoUrl) {
    imgA.classList.remove('visible');
    imgB.classList.remove('visible');
    currentPhotoUrl = '';
    return;
  }

  if (newPhotoUrl === currentPhotoUrl) {
    return;
  }
  currentPhotoUrl = newPhotoUrl;

  const nextSlot = (currentPhotoSlot === 'a') ? 'b' : 'a';
  const activeImg = (currentPhotoSlot === 'a') ? imgA : imgB;
  const nextImg = (nextSlot === 'a') ? imgA : imgB;

  const preload = new Image();
  preload.onload = () => {
    nextImg.style.transition = 'none';
    nextImg.style.transform = 'scale(1.02)';
    nextImg.src = newPhotoUrl;
    void nextImg.offsetHeight;
    nextImg.style.transition = 'opacity 1.4s cubic-bezier(0.4, 0, 0.2, 1), transform 16s ease-out';
    nextImg.classList.add('visible');
    activeImg.classList.remove('visible');
    currentPhotoSlot = nextSlot;
  };
  preload.onerror = () => {
    activeImg.classList.remove('visible');
  };
  preload.src = newPhotoUrl;
}

function deactivateSpotlight() {
  document.body.classList.remove('spotlight-mode');
  document.getElementById('spotlight-backdrop').classList.remove('active');
  document.getElementById('spotlight-card').classList.remove('active');
  updateSpotlightPhoto('');

  // Glide QR code back to center
  glideQrToCenter();
}

