    return children
}

func inspectElement(_ element: AXUIElement, depth: Int = 0) {
    var descRef: AnyObject?
    AXUIElementCopyAttributeValue(element, kAXDescriptionAttribute as CFString, &descRef)
    let desc = (descRef as? String) ?? ""

