                      !lower.contains("meter") &&
                      !lower.contains("level") &&
                      !lower.contains("headphone") &&
                      !lower.contains("cue") &&
                      !lower.contains("gain") {
                fallbackVolume = val
            }
        }

        if let lineVol = lineVolumeFound {
            trackInfo["volume"] = lineVol
        } else if let fbVol = fallbackVolume {
            trackInfo["volume"] = fbVol
        }

        print("Deck \(deckNumber): title='\(trackInfo["title"] ?? "")', playing=\(trackInfo["is_playing"] ?? ""), volume='\(trackInfo["volume"] ?? "")'")
