                      !lower.contains("level") &&
                      !lower.contains("headphone") &&
                      !lower.contains("cue") &&
                      !lower.contains("gain") {
                fallbackVolume = val
            }
        }

        if let lineVol = lineVolumeFound {
            trackInfo["volume"] = lineVol
        } else if let fbVol = fallbackVolume {
            trackInfo["volume"] = fbVol
        }

