}

func findDecksGroup(_ element: AXUIElement, depth: Int = 0) -> AXUIElement? {
    if depth > 3 { return nil }
    for child in getChildren(element) {
        let label = getLabel(child) ?? ""
        if label == "Decks" || label.contains("Decks") {
