/* Submission Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(10px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 500;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}
.modal-card {
  background: #180d24;
  border: 1px solid rgba(245, 158, 11, 0.4);
  border-radius: 24px;
  padding: 24px 20px;
  width: 100%;
  max-width: 440px;
  text-align: center;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);
  position: relative;
  max-height: 90dvh;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.modal-close {
  position: absolute;
  top: 16px;
  left: 16px;
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 20px;
  cursor: pointer;
}
.modal-song-preview {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #0d0615;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid #2d183f;
  margin: 16px 0 20px;
  text-align: right;
}
.modal-song-thumb {
  width: 76px;
  height: 52px;
  border-radius: 10px;
  object-fit: cover;
  flex-shrink: 0;
}
.modal-field {
  text-align: right;
  margin-bottom: 14px;
}
.modal-label {
  font-size: 12px;
  font-weight: 700;
  color: #cbd5e1;
  margin-bottom: 6px;
  display: block;
}
.modal-input {
  width: 100%;
  background: #0d0615;
  border: 1px solid #2d183f;
  border-radius: 12px;
  padding: 11px 14px;
  font-size: 13px;
  color: #fff;
  font-family: inherit;
  outline: none;
}
.modal-input:focus {
  border-color: #f59e0b;
}
.submit-request-btn {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  border: none;
  border-radius: 14px;
  color: #000;
  font-size: 15px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
  margin-top: 8px;
  transition: all 0.2s;
}
.submit-request-btn:active {
  transform: scale(0.98);
}

/* Photo Upload for Stage Projection */
.photo-actions {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.photo-btn {
  flex: 1;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.2s ease;
}
.photo-btn:hover, .photo-btn:active {
  background: rgba(245, 158, 11, 0.2);
  border-color: rgba(245, 158, 11, 0.5);
  color: #facc15;
}

/* Compact Photo Preview in Request Form Modal */
.photo-compact-preview {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #0d0615;
  border: 1.5px solid rgba(245, 158, 11, 0.45);
  border-radius: 16px;
  padding: 10px 12px;
  margin-top: 8px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);
  animation: fadeInCompact 0.3s ease-out;
}
@keyframes fadeInCompact {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.photo-compact-thumb-wrap {
  position: relative;
  width: 76px;
  height: 48px;
  border-radius: 10px;
  overflow: hidden;
  flex-shrink: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  background: #000;
}
.photo-compact-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.photo-compact-badge {
  position: absolute;
  bottom: 0;
  inset-inline: 0;
  background: rgba(16, 185, 129, 0.92);
  color: #fff;
  font-size: 8.5px;
  font-weight: 900;
  text-align: center;
  padding: 1.5px 0;
  letter-spacing: 0.2px;
}
.photo-compact-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: right;
  min-width: 0;
}
.photo-compact-title {
  font-size: 12px;
  font-weight: 800;
  color: #facc15;
  display: flex;
  align-items: center;
  gap: 4px;
}
.photo-compact-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.photo-edit-btn, .photo-del-btn {
  padding: 5px 11px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: all 0.2s;
}
.photo-edit-btn {
  background: rgba(245, 158, 11, 0.18);
  border: 1px solid rgba(245, 158, 11, 0.5);
  color: #fbbf24;
}
.photo-del-btn {
  background: rgba(244, 63, 94, 0.12);
  border: 1px solid rgba(244, 63, 94, 0.4);
  color: #fb7185;
}
.photo-edit-btn:active, .photo-del-btn:active {
  transform: scale(0.96);
}

/* Full-Screen Interactive Stage Editor */
.stage-editor-fullscreen {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  background: radial-gradient(circle at 50% 15%, #1d0933 0%, #06020c 80%);
  z-index: 600;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: env(safe-area-inset-top, 16px) 16px env(safe-area-inset-bottom, 16px) 16px;
  box-sizing: border-box;
  touch-action: none;
  overflow: hidden;
  user-select: none;
  animation: modalFadeIn 0.25s ease-out;
}
.stage-editor-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 2px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  flex-shrink: 0;
}
.stage-editor-title-wrap {
  text-align: center;
  flex: 1;
}
.stage-editor-title {
  font-size: 15px;
  font-weight: 900;
  color: #facc15;
  letter-spacing: 0.2px;
}
.stage-editor-subtitle {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
}
.stage-editor-close-btn, .stage-editor-reset-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #e2e8f0;
  border-radius: 10px;
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 800;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: all 0.2s;
}
.stage-editor-reset-btn {
  color: #fb7185;
  border-color: rgba(244, 63, 94, 0.35);
}
.stage-editor-close-btn:active, .stage-editor-reset-btn:active {
  transform: scale(0.96);
}
.stage-editor-canvas-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 0;
  min-height: 0;
  overflow: hidden;
}
.stage-sim-screen {
  position: relative;
  width: 100%;
  max-width: 620px;
  aspect-ratio: 16 / 9;
  background: #05020a;
  border-radius: 14px;
  overflow: hidden;
  border: 2px solid rgba(245, 158, 11, 0.55);
  touch-action: none;
  user-select: none;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.9), 0 0 25px rgba(245, 158, 11, 0.25);
  container-type: inline-size;
  flex-shrink: 0;
}
.stage-editor-controls {
  width: 100%;
  max-width: 620px;
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}
.stage-editor-footer {
  padding: 8px 0 4px;
  flex-shrink: 0;
}
.stage-editor-done-btn {
  width: 100%;
  max-width: 620px;
  margin: 0 auto;
  padding: 15px;
