/* Submission Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(10px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 500;
}
.modal-card {
  background: #180d24;
  border: 1px solid rgba(245, 158, 11, 0.4);
  border-radius: 24px;
  padding: 24px 20px;
  width: 100%;
  max-width: 440px;
  text-align: center;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);
  position: relative;
}
.modal-close {
  position: absolute;
  top: 16px;
  left: 16px;
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 20px;
  cursor: pointer;
}
.modal-song-preview {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #0d0615;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid #2d183f;
  margin: 16px 0 20px;
  text-align: right;
}
.modal-song-thumb {
  width: 76px;
  height: 52px;
  border-radius: 10px;
  object-fit: cover;
  flex-shrink: 0;
}
.modal-field {
  text-align: right;
  margin-bottom: 14px;
}
.modal-label {
  font-size: 12px;
  font-weight: 700;
  color: #cbd5e1;
  margin-bottom: 6px;
  display: block;
}
.modal-input {
  width: 100%;
  background: #0d0615;
  border: 1px solid #2d183f;
  border-radius: 12px;
  padding: 11px 14px;
  font-size: 13px;
  color: #fff;
  font-family: inherit;
  outline: none;
}
.modal-input:focus {
  border-color: #f59e0b;
}
.submit-request-btn {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  border: none;
  border-radius: 14px;
  color: #000;
  font-size: 15px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
  margin-top: 8px;
}

/* Photo Upload for Stage Projection */
.photo-actions {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.photo-btn {
  flex: 1;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.2s ease;
}
.photo-btn:hover, .photo-btn:active {
  background: rgba(245, 158, 11, 0.2);
  border-color: rgba(245, 158, 11, 0.5);
  color: #facc15;
}
.photo-preview-wrap {
  margin-top: 10px;
  position: relative;
  display: inline-block;
  width: 100%;
  max-width: 180px;
  border-radius: 14px;
  overflow: hidden;
  border: 2px solid #facc15;
  box-shadow: 0 4px 20px rgba(245, 158, 11, 0.3);
}
.photo-preview-img {
  width: 100%;
  height: 110px;
  object-fit: cover;
  display: block;
}
.photo-remove-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.8);
  color: #f43f5e;
  border: 1px solid rgba(244, 63, 94, 0.6);
  font-size: 13px;
  font-weight: 900;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 30;
}

/* 16:9 Interactive Stage Simulator */
.stage-simulator-wrap {
  margin-top: 12px;
  background: #0d0615;
  border: 1.5px solid rgba(245, 158, 11, 0.4);
  border-radius: 16px;
  padding: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
}
.stage-sim-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  font-weight: 800;
  color: #facc15;
  margin-bottom: 8px;
  padding: 0 2px;
}
.stage-sim-screen {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #05020a;
  border-radius: 12px;
  overflow: hidden;
  border: 1.5px solid rgba(255, 255, 255, 0.15);

