function openModal(track) {
  if (!isRoomActive) {
    showClosedState({ reason: 'inactive' });
    return;
  }
  selectedTrack = track;
  document.getElementById('modal-thumb').src = track.thumbnail;
  document.getElementById('modal-title').innerText = track.title;
  document.getElementById('modal-channel').innerText = track.channel;
  document.getElementById('request-modal').style.display = 'flex';
  document.body.style.overflow = 'hidden';

  // Reset photo state for fresh request
  removeSelectedPhoto();

  setSimPosition(50, 75);
  setSimScale(1.0);
  updateSimContent();
  initSimDrag();

  const nameInput = document.getElementById('requester-name');
  const noteInput = document.getElementById('requester-note');
  if (nameInput) nameInput.oninput = updateSimContent;
  if (noteInput) noteInput.oninput = updateSimContent;
}

function openStageEditor() {
  const editor = document.getElementById('stage-editor-modal');
  if (editor) {
    editor.style.display = 'flex';
  }
  document.body.style.overflow = 'hidden';
  updateSimContent();
  initSimDrag();
  applySimTransform(false);
}

function closeStageEditor() {
  const editor = document.getElementById('stage-editor-modal');
  if (editor) {
    editor.style.display = 'none';
  }
  // If photo is active, show the compact preview in the request modal
  const compactPreview = document.getElementById('photo-compact-preview');
  const actionsBtns = document.getElementById('photo-actions-btns');
  if (selectedPhotoDataUrl) {
    if (compactPreview) compactPreview.style.display = 'flex';
    if (actionsBtns) actionsBtns.style.display = 'none';
    const compactImg = document.getElementById('photo-compact-img');
    if (compactImg) compactImg.src = selectedPhotoDataUrl;
  } else {
    if (compactPreview) compactPreview.style.display = 'none';
    if (actionsBtns) actionsBtns.style.display = 'flex';
  }

  // Check if request-modal is open to maintain scroll lock
  const reqModal = document.getElementById('request-modal');
  if (reqModal && reqModal.style.display === 'flex') {
    document.body.style.overflow = 'hidden';
  } else {
    document.body.style.overflow = '';
  }
}

function handlePhotoSelected(input) {
  const file = input && input.files && input.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      // Downscale to max 1280px on largest dimension for lightweight ~60-80KB transfer
      const maxDim = 1280;
      let w = img.width;
      let h = img.height;
      if (w > maxDim || h > maxDim) {
        if (w > h) {
          h = Math.round((h * maxDim) / w);
          w = maxDim;
        } else {
          w = Math.round((w * maxDim) / h);
          h = maxDim;
        }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);

      selectedPhotoDataUrl = canvas.toDataURL('image/jpeg', 0.82);
      const simBg = document.getElementById('stage-sim-bg');
      const compactImg = document.getElementById('photo-compact-img');

      if (simBg) simBg.src = selectedPhotoDataUrl;
      if (compactImg) compactImg.src = selectedPhotoDataUrl;

      // Open full-screen editor immediately so user can preview and position text
      openStageEditor();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function removeSelectedPhoto() {
  selectedPhotoDataUrl = null;
  selectedTextPosition = { x: 50, y: 75 };
  selectedTextScale = 1.0;
  setSimScale(1.0);
  const cam = document.getElementById('photo-camera-input');
  const gal = document.getElementById('photo-gallery-input');
  if (cam) cam.value = '';
  if (gal) gal.value = '';

  const compactPreview = document.getElementById('photo-compact-preview');
  if (compactPreview) compactPreview.style.display = 'none';
  const compactImg = document.getElementById('photo-compact-img');
  if (compactImg) compactImg.src = '';
  const simBg = document.getElementById('stage-sim-bg');
  if (simBg) simBg.src = '';
  const actionsBtns = document.getElementById('photo-actions-btns');
  if (actionsBtns) actionsBtns.style.display = 'flex';

  const editor = document.getElementById('stage-editor-modal');
  if (editor && editor.style.display === 'flex') {
    editor.style.display = 'none';
  }
}

function closeModal() {
  document.getElementById('request-modal').style.display = 'none';
  const editor = document.getElementById('stage-editor-modal');
  if (editor) editor.style.display = 'none';
  document.body.style.overflow = '';
  selectedTrack = null;
  removeSelectedPhoto();
  const nameInput = document.getElementById('requester-name');
  const noteInput = document.getElementById('requester-note');
  if (nameInput) nameInput.value = '';
  if (noteInput) noteInput.value = '';
}

