async function generateStoryCard(ticket) {
  const canvas = document.getElementById('story-canvas');
  const previewImg = document.getElementById('story-preview-img');
  const modal = document.getElementById('story-card-modal');
  if (!canvas || !previewImg || !modal) return;

  const ctx = canvas.getContext('2d');
  const W = 1080;
  const H = 1920;
  canvas.width = W;
  canvas.height = H;

  // 1. Luxury Dark Gradient Background
  const bgGrad = ctx.createRadialGradient(W / 2, H * 0.35, 100, W / 2, H / 2, W * 0.95);
  bgGrad.addColorStop(0, '#241038');
  bgGrad.addColorStop(0.45, '#120520');
  bgGrad.addColorStop(1, '#05010a');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);

  // Gold Nebula Glow Accent at Top & Bottom
  const topNebula = ctx.createRadialGradient(W / 2, 0, 50, W / 2, 0, 600);
  topNebula.addColorStop(0, 'rgba(245, 158, 11, 0.25)');
  topNebula.addColorStop(0.6, 'rgba(236, 72, 153, 0.12)');
  topNebula.addColorStop(1, 'transparent');
  ctx.fillStyle = topNebula;
  ctx.fillRect(0, 0, W, H);

  // 2. Vinyl Grooves Background Texture
  ctx.save();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.035)';
  ctx.lineWidth = 1.5;
  for (let r = 180; r < 950; r += 24) {
    ctx.beginPath();
    ctx.arc(W / 2, 850, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();

  // 3. Top Header: ONYX DJ™ Branding
  ctx.textAlign = 'center';

  const badgeW = 460;
  const badgeH = 56;
  const badgeX = (W - badgeW) / 2;
  const badgeY = 130;
  ctx.fillStyle = 'rgba(245, 158, 11, 0.15)';
  ctx.beginPath();
  ctx.roundRect(badgeX, badgeY, badgeW, badgeH, 28);
  ctx.fill();
  ctx.strokeStyle = 'rgba(245, 158, 11, 0.5)';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#fde68a';
  ctx.font = 'bold 22px "Space Grotesk", "Heebo", sans-serif';
  ctx.fillText('ONYX DJ™ • LIVE EXPERIENCE', W / 2, badgeY + 36);

  ctx.fillStyle = '#ffffff';
  ctx.font = '900 48px "Heebo", sans-serif';
  ctx.fillText('השיר שהקפיץ את הרחבה! 🎉', W / 2, 260);

  const activeDjName = document.getElementById('active-dj-title')?.innerText || 'DJ SHAZZ & DJ SONIC';
  ctx.fillStyle = '#fb923c';
  ctx.font = 'bold 26px "Space Grotesk", sans-serif';
  ctx.fillText(`🎧 ${activeDjName}`, W / 2, 310);

  // 4. Center Visual: Guest Real Photo or Turntable Vinyl
  const imgSize = 560;
  const imgX = (W - imgSize) / 2;
  const imgY = 400;

  const imgSrc = ticket.photo || ticket.thumbnail;
  if (imgSrc) {
    try {
      const img = await loadImage(imgSrc);

      ctx.save();
      ctx.shadowColor = ticket.photo ? 'rgba(236, 72, 153, 0.5)' : 'rgba(245, 158, 11, 0.4)';
      ctx.shadowBlur = 45;
      ctx.shadowOffsetY = 15;

      ctx.beginPath();
      ctx.roundRect(imgX, imgY, imgSize, imgSize, 36);
      ctx.fillStyle = '#000000';
      ctx.fill();
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      ctx.roundRect(imgX, imgY, imgSize, imgSize, 36);
      ctx.clip();
      ctx.drawImage(img, imgX, imgY, imgSize, imgSize);
      ctx.restore();

      ctx.save();
      ctx.strokeStyle = ticket.photo ? 'rgba(244, 114, 182, 0.7)' : 'rgba(245, 158, 11, 0.6)';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.roundRect(imgX, imgY, imgSize, imgSize, 36);
      ctx.stroke();
      ctx.restore();

      if (ticket.photo) {
        ctx.fillStyle = '#db2777';
        ctx.beginPath();
        ctx.roundRect(imgX + imgSize - 140, imgY + 20, 120, 44, 22);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 20px "Heebo", sans-serif';
        ctx.fillText('📸 LIVE', imgX + imgSize - 80, imgY + 50);
      }
    } catch(e) {
      console.warn('Failed loading image for canvas:', e);
    }
  }

  // 5. Track Details & Requester
  const metaY = imgY + imgSize + 90;

  ctx.fillStyle = '#ffffff';
  ctx.font = '900 46px "Heebo", sans-serif';
  wrapCanvasText(ctx, ticket.title || 'שיר נבחר', W / 2, metaY, 920, 56);

  const requesterY = metaY + 140;
  ctx.fillStyle = 'rgba(168, 85, 247, 0.2)';
  ctx.beginPath();
  ctx.roundRect((W - 520) / 2, requesterY - 35, 520, 60, 30);
  ctx.fill();
  ctx.strokeStyle = 'rgba(168, 85, 247, 0.5)';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#e9d5ff';
  ctx.font = 'bold 28px "Heebo", sans-serif';
  ctx.fillText(`הוקדש באהבה ע״י ${ticket.requester || 'אורח ברחבה'} ❤️`, W / 2, requesterY + 7);

  if (ticket.note) {
    ctx.fillStyle = '#fde047';
    ctx.font = 'italic 500 30px "Heebo", sans-serif';
    wrapCanvasText(ctx, `“${ticket.note}”`, W / 2, requesterY + 80, 880, 40);
  }

  // 6. Footer: Dynamic QR Code & Official Copyright
  const qrSize = 150;
  const qrX = (W - qrSize) / 2;
  const qrY = H - 320;

  try {
    const qrUrl = window.location.href;
    const qrDataUrl = await generateQrDataUrl(qrUrl, qrSize);
    if (qrDataUrl) {
      const qrImg = await loadImage(qrDataUrl);

      ctx.save();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.roundRect(qrX - 10, qrY - 10, qrSize + 20, qrSize + 20, 16);
      ctx.fill();
      ctx.drawImage(qrImg, qrX, qrY, qrSize, qrSize);
      ctx.restore();
    }
  } catch(e) {}

  ctx.fillStyle = '#94a3b8';
  ctx.font = '600 22px "Heebo", sans-serif';
  ctx.fillText('סרקו גם אתם להזמנת שיר באירוע 📲', W / 2, qrY + qrSize + 45);

  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.font = '500 18px "Space Grotesk", sans-serif';
  ctx.fillText('© 2026 Onyx DJ™ Systems by Meir.Y • All rights reserved.', W / 2, H - 45);

  canvas.toBlob((blob) => {
    currentStoryBlob = blob;
    const dataUrl = URL.createObjectURL(blob);
    previewImg.src = dataUrl;
    modal.classList.add('open');
  }, 'image/png');
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('Image load failed'));
    img.src = src;
  });
}

function generateQrDataUrl(text, size) {
  return new Promise((resolve) => {
    if (!window.QRCode) return resolve(null);
    const tempDiv = document.createElement('div');
    new window.QRCode(tempDiv, {
      text: text,
      width: size,
      height: size,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: window.QRCode.CorrectLevel.M
    });
    setTimeout(() => {
      const img = tempDiv.querySelector('img');
      const canvas = tempDiv.querySelector('canvas');
      if (img && img.src) resolve(img.src);
      else if (canvas) resolve(canvas.toDataURL('image/png'));
      else resolve(null);
    }, 100);
  });
}

function wrapCanvasText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = (text || '').split(' ');
  let line = '';
  let testY = y;
  for (let n = 0; n < words.length; n++) {
    const testLine = line + words[n] + ' ';
    const metrics = ctx.measureText(testLine);
    if (metrics.width > maxWidth && n > 0) {
      ctx.fillText(line.trim(), x, testY);
      line = words[n] + ' ';
      testY += lineHeight;
    } else {
      line = testLine;
    }
  }
  ctx.fillText(line.trim(), x, testY);
}

async function shareStoryCard() {
  if (!currentStoryBlob) {
    alert('התמונה עדיין מעובדת, נסו שוב בעוד רגע');
    return;
  }
  const file = new File([currentStoryBlob], 'onyx-dj-story.png', { type: 'image/png' });

  if (navigator.canShare && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({
        files: [file],
        title: 'השיר שלי ב-ONYX DJ™',
        text: 'ביקשתי שיר ברחבה והדיג\'יי ניגן אותו! 🔥 #OnyxDJ'
      });
    } catch(e) {
      if (e.name !== 'AbortError') downloadStoryCard();
    }
  } else {
    downloadStoryCard();
  }
}

function downloadStoryCard() {
  if (!currentStoryBlob) return;
  const url = URL.createObjectURL(currentStoryBlob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `onyx-story-${Date.now()}.png`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// 3. MQTT WEBSOCKET BROKER LISTENER (HiveMQ + EMQX with Notify & Crowd FX support)
function initMqttStatusListener() {
  const statusTopic = `onyx/status/${cleanRoom}`;
  const notifyTopic = `onyx/requests/${cleanRoom}/notify`;
  const fxTopic = `onyx/stage/${cleanRoom}/fx`;
  const PahoLib = window.Paho;
  const Client = (PahoLib && PahoLib.MQTT && PahoLib.MQTT.Client) || (PahoLib && PahoLib.Client);
  if (!Client) return;

  const handleMsg = (msg) => {
    try {
      const topic = msg.destinationName || '';
      const payload = JSON.parse(msg.payloadString);
      console.log('[Guest MQTT] Received on', topic, payload);

      if (topic.includes('/fx')) {
        handleCrowdFx(payload);
      } else if (topic.includes('/notify')) {
        handleGuestNotification(payload);
      } else {
        applyRoomStatus(payload);
      }
    } catch(e) {
      console.warn('[Guest MQTT] Error parsing message payload:', e);
    }
  };

  try {
    const clientId = 'guest_st_' + Math.random().toString(36).substring(2, 9);
    mqttStatusClient = new Client('broker.hivemq.com', 8884, '/mqtt', clientId);
    mqttStatusClient.onMessageArrived = handleMsg;
    mqttStatusClient.onConnectionLost = () => setTimeout(initMqttStatusListener, 4000);
    mqttStatusClient.connect({
      useSSL: true,
      timeout: 4,
      cleanSession: true,
      onSuccess: () => {
        mqttStatusClient.subscribe(statusTopic, { qos: 0 });
        mqttStatusClient.subscribe(notifyTopic, { qos: 0 });
        mqttStatusClient.subscribe(fxTopic, { qos: 0 });
        if (cleanRoom !== 'SHAZZ-SONIC') {
          mqttStatusClient.subscribe('onyx/status/SHAZZ-SONIC', { qos: 0 });
          mqttStatusClient.subscribe('onyx/stage/SHAZZ-SONIC/fx', { qos: 0 });
        }
      },
      onFailure: tryEmqxFallback
    });
  } catch(e) {
    tryEmqxFallback();
  }

  function tryEmqxFallback() {
    try {
      const fbId = 'guest_st_fb_' + Math.random().toString(36).substring(2, 9);
      const emqx = new Client('broker.emqx.io', 8084, '/mqtt', fbId);
      emqx.onMessageArrived = handleMsg;
      emqx.connect({
        useSSL: true,
        timeout: 4,
        cleanSession: true,
        onSuccess: () => {
          emqx.subscribe(statusTopic, { qos: 0 });
          emqx.subscribe(notifyTopic, { qos: 0 });
          emqx.subscribe(fxTopic, { qos: 0 });
          if (cleanRoom !== 'SHAZZ-SONIC') {
            emqx.subscribe('onyx/status/SHAZZ-SONIC', { qos: 0 });
            emqx.subscribe('onyx/stage/SHAZZ-SONIC/fx', { qos: 0 });
          }
        }
      });
    } catch(e) {}
  }
}

