let isQrCorner = false;
function glideQrToCorner() {
  isQrCorner = true;
  const qr = document.getElementById('stage-qr-card');
  if (!qr) return;
  const rect = qr.getBoundingClientRect();
  const currentX = rect.left;
  const currentY = rect.top;
  const targetX = 32;
  const targetY = 32;
  const deltaX = targetX - currentX;
  const deltaY = targetY - currentY;

  qr.style.transform = `translate(${deltaX}px, ${deltaY}px) scale(0.62)`;
