iOS Safari requires a user gesture, like a tap, to unmute an `AudioContext`. Submitting a request inherently involves a tap on the submit button. Therefore, initializing and resuming the audio context during any click or tap ensures that subsequent chimes play without restriction.
```javascript
let guestAudioCtx = null;
function unlockAudioContext() {
  if (!guestAudioCtx) {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (AudioCtx) {
      guestAudioCtx = new AudioCtx();
    }
  }
  if (guestAudioCtx.state === 'suspended') {
    guestAudioCtx.resume();
  }
}
```

