// ========================================================
// FEATURE 3: LIVE GUEST TICKETS & NOTIFICATION LOGIC
// ========================================================
let currentActiveNotifyTicket = null;
let toastTimeout = null;
let guestAudioCtx = null;
window._sessionTickets = window._sessionTickets || [];
window._photoCache = window._photoCache || new Map();
const processedNotifications = new Set();

function unlockAudioContext() {
  try {
    if (!guestAudioCtx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) guestAudioCtx = new AudioCtx();
    }
    if (guestAudioCtx && guestAudioCtx.state === 'suspended') {
      guestAudioCtx.resume();
    }
  } catch(e) {}
}
document.addEventListener('click', unlockAudioContext, { passive: true });
document.addEventListener('touchstart', unlockAudioContext, { passive: true });

function cleanupLocalStorageQuota() {
  try {
    for (let i = localStorage.length - 1; i >= 0; i--) {
      const k = localStorage.key(i);
      if (k && (k.startsWith('onyx_requests_') || k.startsWith('onyx_debug_'))) {
        localStorage.removeItem(k);
      }
    }
    const key = getMyTicketsKey();
    const raw = localStorage.getItem(key);
    if (raw) {
      const tickets = JSON.parse(raw);
      const sanitized = tickets.map(t => {
        if (t.photo && t.photo.length > 3000) {
          return { ...t, photo: null, hasPhoto: true };
        }
        return t;
      }).slice(0, 10);
      localStorage.setItem(key, JSON.stringify(sanitized));
    }
  } catch(e) {
    console.warn('[Storage Cleanup] Handled:', e);
  }
}

function getMyTicketsKey() {
  return 'onyx_my_tickets_' + cleanRoom;
}

function getMyTickets() {
  try {
    return JSON.parse(localStorage.getItem(getMyTicketsKey()) || '[]');
  } catch(e) {
    return [];
  }
}

function saveMyRequest(req) {
  if (!req) return;
  try {
    if (!window._sessionTickets) window._sessionTickets = [];
    window._sessionTickets = window._sessionTickets.filter(t => t.id !== req.id);
    window._sessionTickets.unshift(req);

    if (req.photo) {
      if (!window._photoCache) window._photoCache = new Map();
      window._photoCache.set(req.id, req.photo);
    }

    const tickets = getMyTickets();
    const lightweightReq = {
      id: req.id,
      title: req.title,
      channel: req.channel,
      url: req.url,
      thumbnail: req.thumbnail,
      requester: req.requester,
      note: req.note,
      hasPhoto: !!req.photo,
      timestamp: req.timestamp || Date.now(),
      status: req.status || 'pending'
    };

    const filtered = tickets.filter(t => t.id !== req.id);
    filtered.unshift(lightweightReq);

    try {
      localStorage.setItem(getMyTicketsKey(), JSON.stringify(filtered.slice(0, 10)));
    } catch (quotaErr) {
      console.warn('[Storage Quota] Auto-pruning to preserve tickets:', quotaErr);
      cleanupLocalStorageQuota();
      try {
        localStorage.setItem(getMyTicketsKey(), JSON.stringify(filtered.slice(0, 4)));
      } catch(e2) {}
    }
  } catch(err) {
    console.warn('[saveMyRequest error]', err);
  }
  renderMyTickets();
}

function updateTicketStatus(reqId, newStatus) {
  if (window._sessionTickets) {
    window._sessionTickets = window._sessionTickets.map(t => {
      if (t.id === reqId || (!reqId && t.status !== newStatus)) {
        return { ...t, status: newStatus };
      }
      return t;
    });
  }
  const tickets = getMyTickets();
  let updated = false;
  const newList = tickets.map(t => {
    if (t.id === reqId || (!reqId && t.status !== newStatus)) {
      updated = true;
      return { ...t, status: newStatus };
    }
    return t;
  });
  if (updated) {
    try {
      localStorage.setItem(getMyTicketsKey(), JSON.stringify(newList));
    } catch(e) {}
    renderMyTickets();
  }
  return updated;
}

function renderMyTickets() {
  const wrap = document.getElementById('my-tickets-wrap');
  const list = document.getElementById('my-tickets-list');
  const countBadge = document.getElementById('my-tickets-count-badge');
  if (!wrap || !list) return;

  const tickets = getMyTickets();
  if (!tickets || tickets.length === 0) {
    wrap.style.display = 'none';
    return;
  }

  wrap.style.display = 'block';
  if (countBadge) countBadge.innerText = `${tickets.length} ${tickets.length === 1 ? 'שיר' : 'שירים'}`;

  list.innerHTML = tickets.map((t, idx) => {
    const isUpNext = t.status === 'up_next';
    const isPlaying = t.status === 'playing';

    let badgeHtml = '';
    if (isPlaying) {
      badgeHtml = `
        <span class="ticket-badge-status ticket-badge-playing">
          <span class="eq-bars">
            <span class="eq-bar"></span><span class="eq-bar"></span><span class="eq-bar"></span>
          </span>
          מתנגן עכשיו ברחבה! 🎧
        </span>
      `;
    } else if (isUpNext) {
      badgeHtml = `
        <span class="ticket-badge-status ticket-badge-up-next">
          🔥 עולה בעוד 2 שירים! היכון לרחבה!
        </span>
      `;
    } else if (t.status === 'ready') {
      badgeHtml = `
        <span class="ticket-badge-status ticket-badge-ready">
          ✨ אושר ע״י הדיג'יי (ינוגן בהמשך)
        </span>
      `;
    } else {
      badgeHtml = `
        <span class="ticket-badge-status ticket-badge-pending">
          ⏳ ממתין לבדיקת הדיג'יי
        </span>
      `;
    }

    const thumb = (window._photoCache && window._photoCache.get(t.id)) || t.photo || t.thumbnail || 'favicon.png';

    return `
      <div class="my-ticket-card ${isUpNext ? 'is-up-next' : ''} ${isPlaying ? 'is-playing' : ''}" id="ticket-${t.id}">
        <div class="my-ticket-header">
          <span style="font-size: 11px; font-weight: 800; color: #a78bfa; font-family: monospace;">#0${idx + 1}</span>
          ${badgeHtml}
        </div>

        <div class="ticket-song-row">
          <img src="${thumb}" class="ticket-song-thumb" alt="" />
          <div class="ticket-song-info">
            <div class="ticket-song-title" title="${t.title}">${t.title}</div>
            <div class="ticket-requester-sub">
              <span>👤 ${t.requester || 'אורח'}</span>
              ${t.note ? `<span style="color: #facc15; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">• "${t.note}"</span>` : ''}
            </div>
          </div>
        </div>

        <div class="ticket-actions-bar">
          <span style="font-size: 10px; color: #64748b;">ONYX DJ™ • REQUEST TRACKER</span>
          <button type="button" class="ticket-story-btn" onclick="openStoryCardForTicket('${t.id}')">
            <span>📸 סטורי מזכרת ממותג</span>
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function playGuestChime() {
  try {
    unlockAudioContext();
    const ctx = guestAudioCtx || new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(523.25, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1046.50, ctx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.25, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.4);
  } catch (e) {}
}

function isNotificationForMe(payload) {
  if (!payload) return false;
  const allTickets = [
    ...(window._sessionTickets || []),
    ...getMyTickets()
  ];
  // 1. Direct ID match
  if (payload.reqId && allTickets.some(t => t.id === payload.reqId)) {
    return true;
  }
  // 2. Requester name match
  const savedName = (localStorage.getItem('onyx_guest_name') || '').trim().toLowerCase();
  const currentInputName = (document.getElementById('requester-name')?.value || '').trim().toLowerCase();
  const notifRequester = (payload.requester || '').trim().toLowerCase();
  if (notifRequester && notifRequester !== 'אורח אנונימי' && notifRequester !== 'guest') {
    if (savedName && (savedName === notifRequester || notifRequester.includes(savedName) || savedName.includes(notifRequester))) {
      return true;
    }
    if (currentInputName && (currentInputName === notifRequester || notifRequester.includes(currentInputName) || currentInputName.includes(notifRequester))) {
      return true;
    }
    if (allTickets.some(t => (t.requester || '').trim().toLowerCase() === notifRequester)) {
      return true;
    }
  }
  // 3. Song title match
  const notifTitle = (payload.title || '').trim().toLowerCase();
  if (notifTitle && allTickets.some(t => {
    const tTitle = (t.title || '').trim().toLowerCase();
    return tTitle === notifTitle || tTitle.includes(notifTitle) || notifTitle.includes(tTitle);
  })) {
    return true;
  }
  // 4. Fallback: if user sent a request on this device and no other song id was given
  if (allTickets.length > 0 && !payload.reqId) {
    return true;
  }
  return false;
}

function handleGuestNotification(payload) {
  if (!payload) return;

  const dedupeKey = `${payload.type}_${payload.reqId || ''}_${payload.title || ''}`;
  if (processedNotifications.has(dedupeKey)) return;
  processedNotifications.add(dedupeKey);
  setTimeout(() => processedNotifications.delete(dedupeKey), 25000);

  console.log('[Guest Notify] Received live notification:', payload);

  const allTickets = [
    ...(window._sessionTickets || []),
    ...getMyTickets()
  ];

  // Check if this notification is for this device's request
  const isForMe = isNotificationForMe(payload);
  if (!isForMe) {
    console.log('[Guest Notify] Notification is for another guest request, ignoring banner.');
    return;
  }

  let matchingTicket = allTickets.find(t => t.id === payload.reqId) ||
                       allTickets.find(t => t.title && payload.title && t.title.toLowerCase().trim() === payload.title.toLowerCase().trim()) ||
                       (allTickets.length > 0 ? allTickets[0] : null);

  currentActiveNotifyTicket = matchingTicket;
  if (matchingTicket && payload.type) {
    updateTicketStatus(matchingTicket.id, payload.type);
  }

  if (navigator.vibrate) {
    try {
      navigator.vibrate([250, 100, 250, 100, 450]);
    } catch(e) {}
  }

  playGuestChime();

  if (window.confetti) {
    try {
      window.confetti({
        particleCount: 80,
        spread: 70,
        origin: { y: 0.15 },
        colors: ['#f59e0b', '#ec4899', '#8b5cf6', '#10b981', '#ffffff']
      });
    } catch(e) {}
  }

  const toast = document.getElementById('live-notify-toast');
  const icon = document.getElementById('notify-icon');
  const title = document.getElementById('notify-title');
  const desc = document.getElementById('notify-desc');
  if (!toast) return;

  const songName = payload.title || (matchingTicket && matchingTicket.title) || 'השיר שלך';

  if (payload.type === 'up_next') {
    if (icon) icon.innerText = '🔥';
    if (title) title.innerText = 'השיר שלך עולה בעוד 2 שירים!';
    if (desc) desc.innerText = `"${songName}" עולה בקרוב לרמקולים! כולם לרחבה! 💃🕺`;
  } else {
    if (icon) icon.innerText = '🎉';
    if (title) title.innerText = 'השיר שלך מתנגן עכשיו בלייב!';
    if (desc) desc.innerText = `"${songName}" מנוגן כעת ברחבה! תנו בראש! 🎧`;
  }

  toast.classList.add('show');
  if (toastTimeout) clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => {
    closeNotifyToast();
  }, 14000);
}

function closeNotifyToast() {
  const toast = document.getElementById('live-notify-toast');
  if (toast) toast.classList.remove('show');
}

function handleToastClick() {
  closeNotifyToast();
  const wrap = document.getElementById('my-tickets-wrap');
  if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function openStoryCardForCurrentNotify() {
  closeNotifyToast();
  if (currentActiveNotifyTicket) {
    openStoryCardForTicket(currentActiveNotifyTicket.id);
  } else {
    const tickets = getMyTickets();
    if (tickets.length > 0) openStoryCardForTicket(tickets[0].id);
  }
}

// Dual-Engine SSE listener for Port 443 notifications
let notifySseClient = null;
let fxSseClient = null;

function initNotifySseListener() {
  // 1. Live Mobile Notifications via standard HTTPS (Port 443 SSE - 100% cellular reliability)
  try {
    const notifUrl = `https://ntfy.sh/onyx_notify_${cleanRoom.toLowerCase()}/sse`;
    notifySseClient = new EventSource(notifUrl);
    notifySseClient.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.event === 'message') {
          const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
          if (payload) {
            console.log('[SSE Notify] Received live notification:', payload);
            handleGuestNotification(payload);
          }
        }
      } catch(e) {
        console.warn('[SSE Notify] Parse error:', e);
      }
    };
  } catch (err) {
    console.warn('[SSE Notify] Init error:', err);
  }

  // 2. Crowd FX via standard HTTPS (Port 443 SSE)
  try {
    const fxUrl = `https://ntfy.sh/onyx_fx_${cleanRoom.toLowerCase()}/sse`;
    fxSseClient = new EventSource(fxUrl);
    fxSseClient.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.event === 'message') {
          const payload = typeof data.message === 'string' ? JSON.parse(data.message) : data.message;
          if (payload && payload.mode) {
            handleCrowdFx(payload);
          }
        }
      } catch(e) {}
    };
  } catch (err) {}
}

