/* Strobe Flash (Managed via CSS or high-speed JS interval) */
.fx-mode-strobe-on {
  background: #ffffff !important;
  color: #000000 !important;
}
.fx-mode-strobe-rainbow-on {
  opacity: 1 !important;
  color: #000000 !important;
}
.fx-mode-strobe-off {
  background: #000000 !important;
  color: #ffffff !important;
}

/* ======================================================== */
/* FEATURE 5: SOUVENIR STAGE & STORY CARD MODAL             */
/* ======================================================== */
#story-card-modal {
  position: fixed;
  inset: 0;
  background: rgba(4, 1, 10, 0.92);
  backdrop-filter: blur(20px);
  z-index: 99999;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 14px;
  overflow-y: auto;
}
#story-card-modal.open {
  display: flex;
}
.story-modal-card {
  background: rgba(18, 10, 31, 0.96);
  border: 1px solid rgba(245, 158, 11, 0.4);
  border-radius: 28px;
  padding: 20px 18px;
  width: 100%;
  max-width: 390px;
  display: flex;
  flex-direction: column;
  align-items: center;
