/* Strobe Flash (Managed via CSS or high-speed JS interval) */
.fx-mode-strobe-on {
  background: #ffffff !important;
  color: #000000 !important;
}
.fx-mode-strobe-off {
  background: #000000 !important;
  color: #ffffff !important;
}

/* ======================================================== */
/* FEATURE 5: VIRAL SOUVENIR STORY CARD (9:16 MODAL)        */
/* ======================================================== */
#story-card-modal {
  position: fixed;
  inset: 0;
  background: rgba(4, 1, 10, 0.88);
  backdrop-filter: blur(18px);
  z-index: 99999;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px;
  overflow-y: auto;
}
#story-card-modal.open {
  display: flex;
}
.story-modal-card {
  background: rgba(18, 10, 31, 0.95);
  border: 1px solid rgba(245, 158, 11, 0.35);
  border-radius: 28px;
  padding: 24px 20px;
  width: 100%;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.85), 0 0 40px rgba(245, 158, 11, 0.2);
  position: relative;
}
.story-preview-frame {
  width: 220px;
  height: 391px; /* 9:16 aspect ratio */
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.8), 0 0 20px rgba(168, 85, 247, 0.3);
  border: 2px solid rgba(255, 255, 255, 0.2);
  margin: 14px 0;
  background: #000;
}
.story-preview-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

