let currentStoryBlob = null;
let currentStoryTicket = null;
let currentStoryFormat = 'stage'; // 'stage' (16:9) or 'story' (9:16)

function switchStoryFormat(fmt) {
  currentStoryFormat = fmt;
  const stageBtn = document.getElementById('fmt-stage-btn');
  const storyBtn = document.getElementById('fmt-story-btn');
  const frame = document.getElementById('story-preview-frame');
  if (fmt === 'stage') {
    if (stageBtn) stageBtn.classList.add('active');
    if (storyBtn) storyBtn.classList.remove('active');
    if (frame) {
      frame.classList.add('is-stage');
      frame.classList.remove('is-story');
    }
  } else {
    if (stageBtn) stageBtn.classList.remove('active');
    if (storyBtn) storyBtn.classList.add('active');
    if (frame) {
      frame.classList.remove('is-stage');
      frame.classList.add('is-story');
    }
  }
  if (currentStoryTicket) {
    generateStoryCard(currentStoryTicket, fmt);
  }
}

function drawImageProp(ctx, img, x, y, w, h, offsetX = 0.5, offsetY = 0.5) {
  const iw = img.width;
  const ih = img.height;
  const r = Math.min(w / iw, h / ih);
  let nw = iw * r;
  let nh = ih * r;
  let cx, cy, cw, ch, ar = 1;

  if (nw < w) ar = w / nw;                             
  if (Math.abs(ar - 1) < 1e-14 && nh < h) ar = h / nh; 
  nw *= ar;
  nh *= ar;

  cw = iw / (nw / w);
  ch = ih / (nh / h);

  cx = (iw - cw) * offsetX;
  cy = (ih - ch) * offsetY;

  if (cx < 0) cx = 0;
  if (cy < 0) cy = 0;
  if (cw > iw) cw = iw;
  if (ch > ih) ch = ih;

  ctx.drawImage(img, cx, cy, cw, ch, x, y, w, h);
}

function openStoryCardForTicket(ticketId) {
  const allTickets = [
    ...(window._sessionTickets || []),
    ...getMyTickets()
  ];
  const ticket = allTickets.find(t => t.id === ticketId) || (allTickets.length > 0 ? allTickets[0] : null);
  if (!ticket) return;

  const cachedPhoto = (window._photoCache && window._photoCache.get(ticket.id)) || ticket.photo || null;
  const effectiveTicket = { ...ticket, photo: cachedPhoto };

  currentStoryTicket = effectiveTicket;
  generateStoryCard(effectiveTicket, currentStoryFormat);
}

function closeStoryModal() {
  const modal = document.getElementById('story-card-modal');
  if (modal) modal.classList.remove('open');
}

async function generateStoryCard(ticket, format = currentStoryFormat) {
  const canvas = document.getElementById('story-canvas');
  const previewImg = document.getElementById('story-preview-img');
  const modal = document.getElementById('story-card-modal');
  if (!canvas || !previewImg || !modal) return;

  const isStage = (format === 'stage');
  const W = isStage ? 1920 : 1080;
  const H = isStage ? 1080 : 1920;
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');

  // 1. Base dark luxury gradient
  const bgGrad = ctx.createRadialGradient(W / 2, H / 2, 80, W / 2, H / 2, Math.max(W, H) * 0.7);
  bgGrad.addColorStop(0, '#1c0b30');
  bgGrad.addColorStop(0.5, '#0b0416');
  bgGrad.addColorStop(1, '#040108');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);

  // 2. Full-bleed background photo (Cover entire canvas - no wasted empty margins!)
  const imgSrc = ticket.photo || ticket.thumbnail;
  if (imgSrc) {
    try {
      const img = await loadImage(imgSrc);
      ctx.save();
      drawImageProp(ctx, img, 0, 0, W, H);

      // Subtle cinematic dark vignette overlay so text & card pop with maximum contrast
      const vignette = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.25, W / 2, H / 2, Math.max(W, H) * 0.75);
      vignette.addColorStop(0, 'rgba(5, 2, 12, 0.35)');
      vignette.addColorStop(1, 'rgba(5, 2, 12, 0.78)');
      ctx.fillStyle = vignette;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    } catch(e) {
      console.warn('Canvas image load fallback:', e);
    }
  }

  // 3. Top-Left Stage QR Card
  const qrBoxW = isStage ? 180 : 160;
  const qrBoxH = isStage ? 220 : 200;
  const qrBoxX = isStage ? 55 : 45;
  const qrBoxY = isStage ? 45 : 45;
  const qrImgSize = isStage ? 140 : 125;

  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.85)';
  ctx.shadowBlur = 35;
  ctx.shadowOffsetY = 12;

  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.roundRect(qrBoxX, qrBoxY, qrBoxW, qrBoxH, 20);
  ctx.fill();
  ctx.restore();

  try {
    const qrUrl = window.location.href;
    const qrDataUrl = await generateQrDataUrl(qrUrl, qrImgSize);
    if (qrDataUrl) {
      const qrImg = await loadImage(qrDataUrl);
      ctx.drawImage(qrImg, qrBoxX + (qrBoxW - qrImgSize) / 2, qrBoxY + 12, qrImgSize, qrImgSize);
    }
  } catch(e) {}

  ctx.fillStyle = '#0f172a';
  ctx.font = 'bold 13px "Heebo", sans-serif';
  ctx.textAlign = 'center';
  ctx.direction = 'rtl';
  ctx.fillText('סרקו שיר הבא ⚡', qrBoxX + qrBoxW / 2, qrBoxY + qrImgSize + 30);

  ctx.fillStyle = '#d97706';
  ctx.font = '900 13px "Space Grotesk", monospace';
  ctx.fillText('#' + cleanRoom, qrBoxX + qrBoxW / 2, qrBoxY + qrImgSize + 48);

  // 4. Top-Right Brand Badge
  const activeDjName = document.getElementById('active-dj-title')?.innerText || 'DJ SHAZZ & DJ SONIC';
  ctx.save();
  const brandX = isStage ? W - 60 : W / 2;
  const brandY = isStage ? 55 : 290;
  ctx.textAlign = isStage ? 'right' : 'center';

  // ONYX DJ™ Pill
  ctx.fillStyle = 'rgba(10, 4, 18, 0.75)';
  ctx.strokeStyle = 'rgba(245, 158, 11, 0.5)';
  ctx.lineWidth = 1.5;
  ctx.shadowColor = 'rgba(245, 158, 11, 0.3)';
  ctx.shadowBlur = 15;
  const pillW = 340;
  const pillH = 46;
  const pillX = isStage ? brandX - pillW : brandX - pillW / 2;
  ctx.beginPath();
  ctx.roundRect(pillX, brandY, pillW, pillH, 23);
  ctx.fill();
  ctx.stroke();

  ctx.shadowBlur = 0;
  ctx.fillStyle = '#fde68a';
  ctx.font = '900 18px "Space Grotesk", sans-serif';
  ctx.direction = 'ltr';
  ctx.textAlign = 'center';
  ctx.fillText('ONYX DJ™ • LIVE EXPERIENCE', pillX + pillW / 2, brandY + 29);

  // DJ Name subtitle
  ctx.fillStyle = '#fb923c';
  ctx.font = 'bold 16px "Space Grotesk", sans-serif';
  ctx.fillText(`🎧 ${activeDjName}`, pillX + pillW / 2, brandY + 68);
  ctx.restore();

  // 5. Authentic Stage Dedication Card (Identical to Big Screen!)
  const cardW = isStage ? 960 : W - 100;
  const cardMinH = isStage ? 260 : 330;
  const cardX = isStage ? (W - cardW) / 2 : 50;
  const cardY = isStage ? H - cardMinH - 85 : H - cardMinH - 120;

  ctx.save();
  ctx.shadowColor = 'rgba(168, 85, 247, 0.55)';
  ctx.shadowBlur = 40;
  ctx.shadowOffsetY = 15;

  ctx.fillStyle = 'rgba(10, 4, 18, 0.88)';
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.22)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.roundRect(cardX, cardY, cardW, cardMinH, 32);
  ctx.fill();
  ctx.stroke();
  ctx.restore();

  // Inside Dedication Card Elements
  const cardCenterX = cardX + cardW / 2;
  let currY = cardY + 45;

  // Card Header Tag: !מתנגן עכשיו לבקשת הקהל ✨
  ctx.save();
  const tagText = '✨ !מתנגן עכשיו לבקשת הקהל ✨';
  ctx.font = 'bold 18px "Heebo", sans-serif';
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  const tagMetrics = ctx.measureText(tagText);
  const tagW = tagMetrics.width + 36;
  const tagH = 36;
  ctx.fillStyle = 'rgba(245, 158, 11, 0.2)';
  ctx.strokeStyle = 'rgba(245, 158, 11, 0.6)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.roundRect(cardCenterX - tagW / 2, currY - 24, tagW, tagH, 18);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#fde047';
  ctx.fillText(tagText, cardCenterX, currY);
  ctx.restore();

  // Line 1: Requester Name with Heart
  currY += 52;
  ctx.save();
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.font = '900 38px "Heebo", sans-serif';

  const reqGrad = ctx.createLinearGradient(cardCenterX - 200, currY, cardCenterX + 200, currY);
  reqGrad.addColorStop(0, '#ffffff');
  reqGrad.addColorStop(0.5, '#38bdf8');
  reqGrad.addColorStop(1, '#e879f9');
  ctx.fillStyle = reqGrad;
  ctx.shadowColor = 'rgba(56, 189, 248, 0.5)';
  ctx.shadowBlur = 20;

  const requesterName = ticket.requester || 'אורח ברחבה';
  ctx.fillText(`❤️ הוקדש ע״י ${requesterName}`, cardCenterX, currY);
  ctx.restore();

  // Line 2: Personal Note with Quotes
  if (ticket.note && ticket.note.trim()) {
    currY += 54;
    ctx.save();
    ctx.direction = 'rtl';
    ctx.textAlign = 'center';
    ctx.font = 'italic 900 34px "Heebo", sans-serif';

    const noteGrad = ctx.createLinearGradient(cardCenterX - 250, currY, cardCenterX + 250, currY);
    noteGrad.addColorStop(0, '#ffffff');
    noteGrad.addColorStop(0.35, '#fde047');
    noteGrad.addColorStop(0.7, '#fb7185');
    noteGrad.addColorStop(1, '#e879f9');
    ctx.fillStyle = noteGrad;
    ctx.shadowColor = 'rgba(251, 113, 133, 0.5)';
    ctx.shadowBlur = 22;

    ctx.fillText(`“${ticket.note.trim()}”`, cardCenterX, currY);
    ctx.restore();
  }

  // Line 3: Song Title Pill
  currY += 50;
  ctx.save();
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.font = 'bold 22px "Heebo", sans-serif';

  const rawSongTitle = ticket.title || 'שיר לבקשת הקהל';
  const maxTitleChars = isStage ? 60 : 38;
  const songTitle = rawSongTitle.length > maxTitleChars ? rawSongTitle.substring(0, maxTitleChars) + '...' : rawSongTitle;
  const songMetrics = ctx.measureText(`🎵 ${songTitle}`);
  const songPillW = Math.min(cardW - 60, songMetrics.width + 44);
  const songPillH = 42;

  ctx.fillStyle = 'rgba(15, 7, 26, 0.75)';
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.18)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.roundRect(cardCenterX - songPillW / 2, currY - 28, songPillW, songPillH, 21);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#e2e8f0';
  ctx.fillText(`🎵 ${songTitle}`, cardCenterX, currY);
  ctx.restore();

  // 6. Footer Legal
  ctx.save();
  ctx.direction = 'ltr';
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.font = '500 15px "Space Grotesk", sans-serif';
  ctx.fillText('© 2026 Onyx DJ™ Systems by Meir.Y • All rights reserved.', W / 2, H - 22);
  ctx.restore();

  canvas.toBlob((blob) => {
    currentStoryBlob = blob;
    const dataUrl = URL.createObjectURL(blob);
    previewImg.src = dataUrl;
    modal.classList.add('open');
  }, 'image/png');
}

