args.ReplacementContent:
// ========================================================
// SCREEN WAKE LOCK & ANTI-SLEEP ENGINE (HYBRID ARCHITECTURE)
// Combines Hardware WakeLock API + Muted HTML5 Video Loop
// Completely solves iOS Safari & Android mobile sleep timeouts
// ========================================================
let crowdWakeLock = null;
let isAntiSleepActive = true; // Default ON for party atmosphere

// Get or initialize the video element
function getNoSleepVideo() {
  let v = document.getElementById('no-sleep-video');
  if (!v) {
    v = document.createElement('video');
    v.id = 'no-sleep-video';
    v.setAttribute('playsinline', '');
    v.setAttribute('webkit-playsinline', '');
    v.setAttribute('muted', '');
    v.muted = true;
    v.loop = true;
    v.preload = 'auto';
    v.style.position = 'fixed';
    v.style.top = '0';
    v.style.left = '0';
    v.style.width = '1px';
    v.style.height = '1px';
    v.style.opacity = '0.001';
    v.style.pointerEvents = 'none';
    v.style.zIndex = '-999';
    v.src = './nosleep.mp4';
    document.body.appendChild(v);
  }
  return v;
}

// Attach loop protection on video timeupdate to avoid any freeze
function attachVideoLoopGuard(v) {
  if (!v || v.__loopGuardAttached) return;
  v.__loopGuardAttached = true;
  v.addEventListener('timeupdate', () => {
    if (v.currentTime > 0.5) {
      v.currentTime = Math.random() * 0.2;
    }
  });
}

async function acquireAntiSleepLocks() {
  if (!isAntiSleepActive) return;

  // 1. Play Verified Looping HTML5 Video (Hardware AVFoundation keep-awake for iOS Safari)
  try {
    const v = getNoSleepVideo();
    if (v) {
      attachVideoLoopGuard(v);
      v.muted = true;
      const playPromise = v.play();
      if (playPromise !== undefined) {
        playPromise.then(() => {
          console.log('[AntiSleep] Looping video playback active');
        }).catch(err => {
          console.warn('[AntiSleep] Video play waiting for touch gesture:', err);
        });
      }
    }
  } catch (e) {
    console.warn('[AntiSleep] Video error:', e);
  }

  // 2. Hardware Screen Wake Lock API (Official W3C standard)
  try {
    if ('wakeLock' in navigator && (!crowdWakeLock || crowdWakeLock.released)) {
      crowdWakeLock = await navigator.wakeLock.request('screen');
      crowdWakeLock.addEventListener('release', () => {
        console.log('[AntiSleep] Native WakeLock released by OS');
        crowdWakeLock = null;
        // DO NOT turn off the UI chip! The user setting remains active.
        // On next user touch or visibilitychange, it will re-acquire automatically.
      });
      console.log('[AntiSleep] Native WakeLock active');
    }
  } catch (err) {
    console.warn('[AntiSleep] Native lock request failed:', err);
  }

  updateAntiSleepUiState(true);
}

function releaseAntiSleepLocks() {
  isAntiSleepActive = false;
  if (crowdWakeLock) {
    try {
      crowdWakeLock.release();
    } catch(e) {}
    crowdWakeLock = null;
  }
  try {
    const v = document.getElementById('no-sleep-video');
    if (v && !v.paused) {
      v.pause();
    }
  } catch(e) {}
  updateAntiSleepUiState(false);
}

function updateAntiSleepUiState(active) {
  const chip = document.getElementById('anti-sleep-chip');
  const statusPill = document.getElementById('anti-sleep-status');
  const lockBadge = document.getElementById('fx-lock-badge');
  const tapPrompt = document.getElementById('fx-tap-prompt');
  const tapPromptText = document.getElementById('fx-tap-prompt-text');

  if (chip && statusPill) {
    if (active) {
      chip.classList.add('active');
      statusPill.innerText = 'פעיל 🟢';
    } else {
      chip.classList.remove('active');
      statusPill.innerText = 'הפעל';
    }
  }

  if (lockBadge) {
    lockBadge.style.display = active ? 'inline-flex' : 'none';
  }
  if (tapPrompt) {
    if (active) {
      if (tapPromptText) tapPromptText.innerText = '✨ המסך נעול דולק – לא ייכבה!';
      setTimeout(() => {
        if (tapPrompt && isAntiSleepActive) tapPrompt.style.display = 'none';
      }, 2000);
    } else {
      tapPrompt.style.display = 'inline-flex';
      if (tapPromptText) tapPromptText.innerText = 'הקישו בכל מקום במסך למניעת כיבוי!';
    }
  }
}

function manualToggleAntiSleep() {
  if (isAntiSleepActive) {
    releaseAntiSleepLocks();
    showToast('💡 שמירת מסך דולק בוטלה');
  } else {
    isAntiSleepActive = true;
    acquireAntiSleepLocks();
    showToast('🟢 מצב מסיבה: המסך יישאר דולק ברחבה!');
  }
}

function handleOverlayTouchWake(e) {
  if (e) e.stopPropagation();
  acquireAntiSleepLocks();
}

// Universal Gesture Unlock: Every touch ensures locks are actively held
function ensureLocksOnUserInteraction() {
  if (isAntiSleepActive) {
    const v = document.getElementById('no-sleep-video');
    if (!crowdWakeLock || (v && v.paused)) {
      acquireAntiSleepLocks();
    }
  }
}
['touchstart', 'touchend', 'click', 'pointerdown'].forEach(evt => {
  window.addEventListener(evt, ensureLocksOnUserInteraction, { passive: true });
});

// Automatically re-acquire wake lock if user switches back to the tab
document.addEventListener('visibilitychange', async () => {
  if (document.visibilityState === 'visible' && (isAntiSleepActive || currentFxMode)) {
    await acquireAntiSleepLocks();
  }
});

